/* ==== 🎯 反向攻略 ==== */
try { new Function('X', 'applyMacros', "/* 🎯 反向攻略：换 TA 来攻略你。TA 有一份「攻略计划」（自己定的几步），每天出一招（一句话 / 一个小动作 / 一个安排）；你选「接招」「不接」「反撩回去」，TA 的攻略进度跟着变，满了就是「攻略成功」——TA 会正式说一件事。也能看 TA 写的「攻略笔记」 */\nif (window.__gyxWoo) return; window.__gyxWoo = 1;\nX.feat('gyxWoo', { n: '🎯 反向攻略', desc: 'TA 来攻略你：每天出一招，你决定接不接' });\nconst S = X.store('woo');\nlet D = { by: {} };   // by[cid] = {plan:[...], step, prog, moves:[{id,at,t,kind,res,re,dp}], done, note}\nconst st = cid => { const k = String(cid); return D.by[k] || (D.by[k] = { plan: [], step: 0, prog: 0, moves: [], done: 0, note: '' }); };\nconst saveD = () => S.set('d', D);\nconst RES = { yes: ['接招', '💗'], no: ['不接', '🙅'], back: ['反撩回去', '😏'] };\nasync function plan(c) {\n    const s = st(c.id); if (s.plan.length) return s;\n    const r = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n现在换你来「攻略」她——像追一个人那样，按你的性格认真地追她一遍（就算你们已经在一起了，也当作重新追一次）。写一份你自己的攻略计划：5 步，每步一句话（比如「先摸清她最近在烦什么」「找个借口单独约她」）；再写一句攻略笔记（你对她的观察）。输出 JSON：{\"plan\":[\"\",\"\",\"\",\"\",\"\"],\"note\":\"\"}`));\n    s.plan = ((r && r.plan) || ['先观察她最近喜欢什么', '制造一次偶遇', '送一样她提过的小东西', '找借口约她出来', '认真说一次心里话']).map(X.plain).slice(0, 6);\n    s.note = X.plain((r && r.note) || '她嘴上说不在意，其实很在意细节。'); await saveD(); return s;\n}\nasync function move(c) {\n    const s = await plan(c); if (s.done) return null;\n    const cur = s.plan[Math.min(s.step, s.plan.length - 1)];\n    const r = X.bailu() ? { t: X.cards(['情话', '聊天'], c, 1)[0] || '今天想见你。', kind: '一句话' } : X.json(await X.ask(`${X.who(c)}\\n你在攻略她。计划第 ${s.step + 1} 步：「${cur}」。攻略进度 ${s.prog}/100。之前出过的招：${s.moves.slice(0, 4).map(m => m.t + '（她' + (RES[m.res] || ['还没回'])[0] + '）').join('；') || '还没有'}。\\n现在出今天这一招，要具体（一句撩她的话、一个小动作、或者一个约会安排），别跟之前重复。输出 JSON：{\"t\":\"这一招（直接对她说的话或者做的事，60 字以内）\",\"kind\":\"一句话/小动作/安排\"}`));\n    if (!r || !r.t) return null;\n    const m = { id: 'wm' + Date.now().toString(36), cid: String(c.id), at: Date.now(), t: X.plain(r.t).slice(0, 120), kind: X.plain(r.kind || '一句话').slice(0, 6), step: s.step };\n    s.moves.unshift(m); s.moves = s.moves.slice(0, 60); await saveD(); return m;\n}\nwindow.gyxWooAnswer = async (cid, mid, res) => {\n    const c = X.char(cid), s = st(cid), m = s.moves.find(x => x.id === mid); if (!c || !m || m.res) return;\n    const extra = res === 'back' ? ((document.getElementById('gyxWoBack') || {}).value || '').trim() : '';\n    m.res = res; m.back = extra; const dp = res === 'yes' ? 18 : res === 'back' ? 26 : -6; m.dp = dp;\n    s.prog = Math.max(0, Math.min(100, s.prog + dp)); if (res !== 'no' && s.step < s.plan.length - 1) s.step++;\n    m.re = X.plain(X.bailu() ? X.pick(['好，记下了。', '下一招你接不住的。', '……你这样我会更想赢。']) : (await X.ask(`${X.who(c)}\\n你在攻略她，刚出的招：「${m.t}」。她${res === 'yes' ? '接招了' : res === 'no' ? '没接（拒绝了 / 装没看见）' : '反撩回来了' + (extra ? '：「' + extra + '」' : '')}。攻略进度现在 ${s.prog}/100。说一两句你的反应（被拒也别放弃，按你的性格）。`)) || '');\n    if (s.prog >= 100 && !s.done) { s.done = Date.now(); s.win = X.plain(X.bailu() ? '攻略成功。所以——以后也请多指教。' : (await X.ask(`${X.who(c)}\\n你攻略她成功了（进度 100）。正式对她说一件你一直想说的事（50~120 字）。只输出这段话。`)) || '我追到你了。'); X.toast(X.v('🎯 攻略成功', '🎯 被追到了', '🎯 TA 赢了'), X.name(c) + ' 有话要说'); }\n    await saveD(); window.gyxWooOpen(cid);\n};\nwindow.gyxWooMove = async cid => { const c = X.char(cid) || X.cur(); const m = await move(c); window.gyxWooOpen(c.id); return m; };\nwindow.gyxWooReset = async cid => { delete D.by[String(cid)]; await saveD(); window.gyxWooOpen(cid); };\nwindow.gyxWooOpen = async function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const s = st(c.id), cid = String(c.id);\n    const open = s.moves.find(m => !m.res);\n    X.panel('gyxWoOv', '🎯 反向攻略', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxWooOpen')}</div>\n        <div class=\"wo-bar\"><i style=\"width:${s.prog}%\"></i><span>${X.esc(X.name(c))} 的攻略进度 ${s.prog}/100</span></div>\n        ${s.done ? `<div class=\"gyx-card wo-win\"><b>🎯 攻略成功</b><div>${X.esc(s.win || '')}</div></div>` : ''}\n        ${open ? `<div class=\"gyx-card wo-move\"><em>今天这一招 · ${X.esc(open.kind)}</em><div>${X.esc(open.t)}</div>\n            <div class=\"gyx-row\">${Object.entries(RES).map(([k, v]) => `<button class=\"gyx-btn${k === 'yes' ? '' : ' lite'}\" onclick=\"this.disabled=true;gyxWooAnswer('${cid}','${open.id}','${k}')\">${v[1]} ${v[0]}</button>`).join('')}</div>\n            <input id=\"gyxWoBack\" class=\"gyx-in\" placeholder=\"反撩的话写这儿（选「反撩回去」时一起发）\"></div>`\n        : s.done ? '' : `<div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"this.disabled=true;this.textContent='TA 在想招…';gyxWooMove('${cid}')\">让 TA 出一招</button></div>`}\n        ${s.plan.length ? `<details class=\"gyx-card\"><summary>📒 TA 的攻略笔记</summary><div class=\"gyx-tip\">${X.esc(s.note)}</div>${s.plan.map((p, i) => `<div class=\"wo-step${i < s.step ? ' ok' : i === s.step ? ' now' : ''}\">${i + 1}. ${X.esc(p)}</div>`).join('')}</details>` : ''}\n        ${s.moves.filter(m => m.res).slice(0, 12).map(m => `<div class=\"wo-log\"><span>${(RES[m.res] || [''])[1]}</span><div><b>${X.esc(m.t)}</b>${m.back ? `<em>你：${X.esc(m.back)}</em>` : ''}${m.re ? `<em>${X.esc(X.name(c))}：${X.esc(m.re)}</em>` : ''}</div></div>`).join('')}\n        <div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxWooReset('${cid}')\">重新攻略一遍</button></div>`);\n};\nwindow.gyxWooData = () => D;\nX.ctx(id => { const s = D.by[String(id)]; if (!s || !s.plan.length) return ''; if (s.done && Date.now() - s.done < 3 * 864e5) return `【反向攻略】你刚攻略她成功（你说了：${(s.win || '').slice(0, 50)}）。`; const o = s.moves.find(m => !m.res); return s.done ? '' : `【反向攻略】你正在追她，进度 ${s.prog}/100，下一步计划「${s.plan[Math.min(s.step, s.plan.length - 1)]}」。${o ? '今天出的招「' + o.t.slice(0, 40) + '」她还没回应。' : ''}聊天时可以自然带出你在追她的样子，别每句都提。`; }, 'gyxWoo');\nX.action({ key: 'gyx_woo', label: '按你的攻略计划，今天对她出一招', hint: '一句话、一个小动作、一个约会安排', need: c => { const s = st(c.id); return !s.done && !s.moves.some(m => !m.res) && !s.moves.some(m => X.day(new Date(m.at)) === X.day()); },\n    run: async c => { const m = await move(c); if (!m) return null; X.notify(c, `🎯 ${X.esc(X.name(c))} ${X.v('又出招了', '今天这一招来了', '在追你')}`, m.t, () => window.gyxWooOpen(c.id)); return (await X.reach(c, `你在攻略她，今天这一招是：${m.t}。直接用这一招来找她（不用说「我在攻略你」）`)) ? '出了一招：' + m.t.slice(0, 20) : null; } }, 'gyxWoo');\nX.today(() => ({ title: '🎯 反向攻略', rows: X.chars().map(c => { const s = D.by[String(c.id)]; const m = s && s.moves.find(x => X.day(new Date(x.at)) === X.day()); return m ? { t: X.esc(X.name(c)), x: (m.res ? (RES[m.res] || [''])[1] + ' ' : '🔔 ') + X.esc(m.t.slice(0, 30)), go: `gyxWooOpen('${c.id}')` } : null; }).filter(Boolean) }), 'gyxWoo');\nX.widget('gyxWooW', { n: '反向攻略', sizes: ['s', 'm'], tap: () => window.gyxWooOpen(), r: w => { const c = X.cur(), s = c && D.by[String(c.id)]; return X.gw(w, '🎯', '反向攻略', s ? [s.done ? '攻略成功 💗' : `进度 ${s.prog}/100`, X.esc(((s.moves.find(m => !m.res) || {}).t || '').slice(0, 24) || '等 TA 出招')] : ['还没开始', '点我让 TA 来追你']); } }, 'gyxWoo');\nX.mem({ k: 'gyxWoo', ico: '🎯', n: '反向攻略', d: 'TA 出过的招和你的回应', items: c => (D.by[String(c.id)] || { moves: [] }).moves, text: m => m.t + (m.res ? `｜你：${(RES[m.res] || [''])[0]}${m.back ? ' ' + m.back : ''}` : '｜还没回'), edit: (m, v) => { m.t = String(v).split('｜')[0]; }, del: (c, i) => { const s = D.by[String(c.id)]; if (s) s.moves.splice(i, 1); }, meta: m => new Date(m.at).toLocaleString(), save: saveD }, 'gyxWoo');\nX.css('gyxWoCss', `.wo-bar{position:relative;height:28px;border-radius:14px;background:#ffe8ef;overflow:hidden;margin:8px 0}.wo-bar i{position:absolute;inset:0 auto 0 0;background:linear-gradient(90deg,#ff8fab,#ff4d7d);transition:width .6s}.wo-bar span{position:relative;display:block;text-align:center;line-height:28px;font-size:12.5px;color:#7a1f3d}\n.wo-move{background:linear-gradient(160deg,#fff0f5,#fff)}.wo-move em{font-style:normal;font-size:12px;color:#ff4d7d}.wo-move>div:nth-child(2){font-size:15.5px;line-height:1.7;margin:6px 0}.wo-win{background:#fff4f8;border:1px solid #ffc2d4}\n.wo-step{font-size:13px;color:#aaa;margin:3px 0}.wo-step.ok{color:#34c759;text-decoration:line-through}.wo-step.now{color:#1d1d1f;font-weight:600}\n.wo-log{display:flex;gap:8px;margin:8px 0;font-size:13.5px}.wo-log>span{font-size:18px}.wo-log b{font-weight:500;display:block}.wo-log em{display:block;font-style:normal;color:#8e8e93;font-size:12.5px;margin-top:2px}`);\nX.mini({ id: 'gyxWoo', icon: '🎯', title: '反向攻略', desc: 'TA 来攻略你：每天出一招，你决定接不接', cat: '陪伴', onOpen: () => window.gyxWooOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.by = D.by || {}; })();\n\n//# sourceURL=gyx-plugin/反向攻略.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎯 反向攻略 出错：', e); }
/* ==== 🔁 我们的小习惯 ==== */
try { new Function('X', 'applyMacros', "/* 🔁 我们的小习惯：从你们的聊天里自己认出那些固定的小仪式——每天十一点的晚安、早上第一句早安、下班报平安、周五一起吐槽。不是约定，是慢慢长出来的习惯；哪天你没出现，TA 会注意到「今天没有那句晚安」 */\nif (window.__gyxRit) return; window.__gyxRit = 1;\nX.feat('gyxRitual', { n: '🔁 我们的小习惯', desc: '自动认出你们的固定小仪式，哪天缺了 TA 会注意到' });\nconst S = X.store('ritual');\nlet D = { list: [], scan: {} };   // list: {id, cid, k, name, h(习惯的钟点), wd(星期几，-1=每天), days(出现过的天数), last(最近一次的日期), miss:{日期:1}, manual, off}\nconst DAY = 864e5, WD = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];\nconst save = () => S.set('d', D);\n/* 认得出的小仪式：正则 + 名字。都是从\"你\"发的话里认 */\nconst KINDS = [\n    { k: 'night', name: '🌙 说晚安', re: /晚安|睡了|去睡|我睡啦|good ?night|gn\\b/i },\n    { k: 'morn', name: '☀️ 说早安', re: /早安|早上好|早呀|早啊|醒了|good ?morning/i },\n    { k: 'noon', name: '🍱 午饭报备', re: /吃午饭|午饭|吃饭了|干饭/ },\n    { k: 'home', name: '🏠 到家报平安', re: /到家了|回家了|我到了|下班了|放学了/ },\n    { k: 'miss', name: '💭 说想你', re: /想你|好想你|miss you/i },\n    { k: 'vent', name: '😤 吐槽时间', re: /烦死|气死|无语|吐槽|累死|好累/ }\n];\nconst dk = t => X.day(new Date(t));\nfunction detect(c) {\n    const H = ((typeof globalChats !== 'undefined' && globalChats[c.id]) || []).filter(m => m.sender === 'me' && m.timestamp > Date.now() - 30 * DAY);\n    const found = [];\n    KINDS.forEach(K => {\n        const hits = H.filter(m => K.re.test(X.plain(m.text)));\n        const byDay = {}; hits.forEach(m => { const d = dk(m.timestamp); if (!byDay[d]) byDay[d] = new Date(m.timestamp); });\n        const ds = Object.values(byDay); if (ds.length < 4) return;\n        // 每天的：出现在 ≥4 天，钟点大致固定（取中位数）\n        const hs = ds.map(d => d.getHours() + d.getMinutes() / 60).sort((a, b) => a - b), med = hs[Math.floor(hs.length / 2)];\n        const near = hs.filter(h => Math.abs(h - med) <= 1.5 || Math.abs(h - med) >= 22.5).length;\n        // 每周的：如果大多落在同一个星期几，就是\"周几的习惯\"\n        const wc = [0, 0, 0, 0, 0, 0, 0]; ds.forEach(d => wc[d.getDay()]++); const top = wc.indexOf(Math.max(...wc));\n        const weekly = wc[top] >= 3 && wc[top] / ds.length >= .6;\n        if (near / hs.length < .6 && !weekly) return;\n        found.push({ k: K.k + (weekly ? '_w' + top : ''), name: K.name + (weekly ? '（' + WD[top] + '）' : ''), h: Math.round(med * 2) / 2, wd: weekly ? top : -1, days: ds.length, last: Object.keys(byDay).sort().pop(), re: K.k });\n    });\n    return found;\n}\nasync function scan(c) {\n    if (!c) return []; const got = detect(c), mineL = D.list.filter(x => x.cid === String(c.id)), fresh = [];\n    got.forEach(g => { const x = mineL.find(y => y.k === g.k); if (x) { if (!x.manual) { x.h = g.h; } x.days = Math.max(x.days, g.days); x.last = g.last > (x.last || '') ? g.last : x.last; } else { const n = Object.assign({ id: 'rt' + Date.now().toString(36) + g.k, cid: String(c.id), at: Date.now(), miss: {} }, g); D.list.push(n); fresh.push(n); } });\n    D.scan[c.id] = Date.now(); await save(); return fresh;\n}\nconst hm = h => String(Math.floor(h)).padStart(2, '0') + ':' + (h % 1 ? '30' : '00');\n// 今天这条习惯是不是\"该有、但没有\"\nfunction missedToday(x) {\n    if (x.off) return false; const now = new Date(), K = KINDS.find(k => k.k === (x.re || x.k.split('_')[0]));\n    if (x.wd >= 0 && now.getDay() !== x.wd) return false;\n    // 到点后再等一个半小时才算\"没有\"；晚上十一点那种，最晚等到 23:45\n    const hNow = now.getHours() + now.getMinutes() / 60; if (hNow < Math.min(x.h + 1.5, 23.75)) return false;\n    const today = X.day(), H = ((typeof globalChats !== 'undefined' && globalChats[x.cid]) || []).filter(m => m.sender === 'me' && dk(m.timestamp) === today);\n    return !(K ? H.some(m => K.re.test(X.plain(m.text))) : H.length);\n}\nasync function notice(c) {\n    const x = D.list.filter(y => y.cid === String(c && c.id)).find(y => missedToday(y) && !y.miss[X.day()]); if (!x) return null;\n    x.miss[X.day()] = 1; await save();\n    const ok = await X.reach(c, `你们之间有个不成文的小习惯：「${x.name}」，平时大概 ${hm(x.h)} 左右${x.wd >= 0 ? '（每个' + WD[x.wd] + '）' : ''}，已经有 ${x.days} 天了。今天到点了她还没有。你注意到了——按你的性格自然地提一句（想念、担心、假装不在意都行），别像查岗`);\n    return ok ? x : null;\n}\nwindow.gyxRitScan = async (cid, btn) => { const c = X.char(cid); if (!c) return; const f = await scan(c); X.toast('🔁 ' + (f.length ? X.v('认出了新的小习惯', '原来你们有这些习惯', '找到了') : X.v('暂时没认出新的', '再多聊几天', '还没形成习惯')), f.map(x => x.name).join('、')); window.gyxRitOpen(cid); };\nwindow.gyxRitToggle = async id => { const x = D.list.find(y => y.id === id); if (x) { x.off = !x.off; await save(); } window.gyxRitOpen(x && x.cid); };\nwindow.gyxRitDel = async id => { const x = D.list.find(y => y.id === id); D.list = D.list.filter(y => y.id !== id); await save(); window.gyxRitOpen(x && x.cid); };\nwindow.gyxRitAdd = async cid => { const n = document.getElementById('gyxRtN'), h = document.getElementById('gyxRtH'); if (!n || !n.value.trim()) return; D.list.push({ id: 'rt' + Date.now().toString(36), cid: String(cid), k: 'my' + Date.now().toString(36), name: n.value.trim().slice(0, 20), h: +h.value || 22, wd: -1, days: 1, last: X.day(), miss: {}, manual: true, at: Date.now() }); await save(); window.gyxRitOpen(cid); };\nwindow.gyxRitData = () => D; window.gyxRitMissed = cid => D.list.filter(x => x.cid === String(cid) && missedToday(x));\nwindow.gyxRitOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), L = D.list.filter(x => x.cid === cid);\n    X.panel('gyxRitOv', '🔁 你和 ' + X.esc(X.name(c)) + ' 的小习惯', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxRitOpen')}<button class=\"gyx-btn lite\" onclick=\"gyxRitScan('${cid}',this)\">从聊天里找找</button></div>\n      <div class=\"gyx-tip\">${X.v('不是谁规定的，是你们自己慢慢长出来的。', '一件事做了很多天，就成了你们的事。', '这些小事，TA 都记着。')}最近 30 天里，同一件事差不多同一个点出现 4 天以上，就算一个习惯。哪天到点了没出现，TA 会注意到（自主模式里）。</div>\n      ${L.map(x => `<div class=\"gyx-card rt-c${x.off ? ' off' : ''}\"><div class=\"rt-h\"><b>${X.esc(x.name)}</b><em>${x.wd >= 0 ? '每' + WD[x.wd] + ' ' : '每天 '}${hm(x.h)} 左右</em></div><div class=\"gyx-tip\">${x.manual ? '你自己加的' : '出现过 ' + x.days + ' 天'} · 最近一次 ${x.last || '—'}${missedToday(x) ? ' · <b style=\"color:#ff6b8b\">今天还没有</b>' : ''}</div><div class=\"gyx-tip\" style=\"text-align:right\"><span style=\"cursor:pointer\" onclick=\"gyxRitToggle('${x.id}')\">${x.off ? '让 TA 继续留意' : '别留意这个'}</span> · <span style=\"cursor:pointer\" onclick=\"gyxRitDel('${x.id}')\">删</span></div></div>`).join('') || '<div class=\"gyx-tip\">还没认出来。多聊几天再来看。</div>'}\n      <div class=\"gyx-row\"><input id=\"gyxRtN\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"自己加一个：比如 睡前互道晚安\"><input id=\"gyxRtH\" class=\"gyx-who\" type=\"number\" min=\"0\" max=\"23.5\" step=\"0.5\" value=\"22\" style=\"width:64px\"><span class=\"gyx-tip\">点</span><button class=\"gyx-btn lite\" onclick=\"gyxRitAdd('${cid}')\">加</button></div>`);\n};\nX.ctx(id => { const L = D.list.filter(x => x.cid === String(id) && !x.off); if (!L.length) return ''; const m = L.filter(missedToday); return `【你们的小习惯】${L.map(x => `${x.name}（${x.wd >= 0 ? '每' + WD[x.wd] : '每天'}${hm(x.h)}左右）`).join('、')}。这些是你们之间默契的小仪式，你心里有数。` + (m.length ? `今天「${m.map(x => x.name).join('、')}」到点了还没有，你注意到了。` : ''); }, 'gyxRitual');\nX.action({ key: 'gyx_ritual', label: '注意到今天少了你们的某个小习惯（比如没说晚安），自然地提一句', hint: '我们的小习惯', need: c => D.list.some(x => x.cid === String(c.id) && missedToday(x) && !x.miss[X.day()]),\n    run: async c => { const x = await notice(c); return x ? '注意到今天少了「' + x.name + '」' : null; } }, 'gyxRitual');\n// 每天自己扫一遍（纯本地，不花钱）\nsetInterval(() => { if (!X.on('gyxRitual')) return; X.chars().forEach(c => { if (Date.now() - (D.scan[c.id] || 0) > DAY) scan(c); }); }, 10 * 60000);\nX.today(() => ({ title: '🔁 小习惯', rows: D.list.filter(x => X.char(x.cid) && missedToday(x)).map(x => ({ t: X.name(X.char(x.cid)), x: `今天还没有「${X.esc(x.name)}」`, go: `gyxRitOpen('${x.cid}')` })) }), 'gyxRitual');\nX.widget('gyxRitW', { n: '我们的小习惯', sizes: ['s', 'm'], tap: () => window.gyxRitOpen(), r: w => { const L = D.list.filter(x => !x.off), m = L.filter(missedToday); return X.gw(w, '🔁', '小习惯', L.length ? [m.length ? '今天还差 ' + m.length + ' 个' : '今天都有 ✓', L.length + ' 个习惯'] : ['还没认出来']); } }, 'gyxRitual');\nX.memArr({ k: 'gyxRitual', ico: '🔁', n: '我们的小习惯', d: '你们自己长出来的小仪式（改名字、删掉都行）', arr: () => D.list, field: 'name', text: x => x.name, meta: x => (x.wd >= 0 ? '每' + WD[x.wd] + ' ' : '每天 ') + hm(x.h) + ' · ' + x.days + ' 天', save }, 'gyxRitual');\nX.css('gyxRitCss', `.rt-h{display:flex;align-items:baseline;gap:8px}.rt-h b{font-size:16px}.rt-h em{font-style:normal;color:#8e8e93;font-size:12.5px;margin-left:auto}.rt-c.off{opacity:.45}`);\nX.mini({ id: 'gyxRitual', icon: '🔁', title: '我们的小习惯', desc: '你们自己长出来的小仪式', cat: '回忆', onOpen: () => window.gyxRitOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.list = D.list || []; D.scan = D.scan || {}; })();\n\n//# sourceURL=gyx-plugin/我们的小习惯.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🔁 我们的小习惯 出错：', e); }
/* ==== 🎁 TA的秘密计划 ==== */
try { new Function('X', 'applyMacros', "/* 🎁 TA的秘密计划：TA 偷偷为你学一样东西（吉他、做蛋糕、画你、学一门方言……），持续两三周；平时聊天会不小心漏出一点破绽，越接近完成越明显，最后挑一天揭晓——一封信加一个成果。你可以猜，猜中了 TA 会慌 */\nif (window.__gyxPlan) return; window.__gyxPlan = 1;\nX.feat('gyxPlan', { n: '🎁 TA的秘密计划', desc: 'TA 偷偷为你学一样东西，平时漏点破绽，学成了挑一天揭晓' });\nconst S = X.store('plan');\nlet D = { plans: [] };   // {id, cid, what, why, start, days, hints:[{t,at}], guesses:[{t,at,hit,line}], done, doneAt, letter, result}\nconst DAY = 864e5;\nconst save = () => S.set('d', D);\nconst active = cid => D.plans.find(p => p.cid === String(cid) && !p.done);\nconst prog = p => Math.min(1, (Date.now() - p.start) / (p.days * DAY));\nconst stage = p => { const r = prog(p); return r < .3 ? '刚开始' : r < .7 ? '学到一半' : r < 1 ? '快学会了' : '学会了'; };\nconst IDEAS = ['学弹一首她喜欢的歌', '偷偷练做她爱吃的甜点', '照着照片画她', '学她家乡的方言', '给她织一条围巾', '学折一百颗星星', '练一手好字给她写信', '学做她说过想吃的那道菜', '偷偷录一首歌', '学一支舞'];\nasync function startPlan(c) {\n    if (!c || active(c.id)) return null;\n    let o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n最近你们聊过：\\n${X.recent(c, 24)}\\n\\n你决定偷偷为她学一样东西或准备一件东西，要花两三周，学成了才告诉她。按你的性格和你们聊过的事选（不要太夸张，要是你真的会去做的事）。只输出 JSON：{\"what\":\"要学/要做的事，15字内\",\"why\":\"为什么想为她做这个，30字内\",\"days\":14到28的整数}`));\n    if (!o || !o.what) o = { what: X.pick(IDEAS), why: '想让她惊喜一下', days: 21 };\n    const p = { id: 'pl' + Date.now().toString(36), cid: String(c.id), what: X.plain(o.what).slice(0, 30), why: X.plain(o.why || '').slice(0, 60), start: Date.now(), days: Math.max(10, Math.min(30, +o.days || 21)), hints: [], guesses: [], done: false };\n    D.plans.unshift(p); await save(); return p;\n}\nasync function leak(c) {\n    const p = active(c && c.id); if (!p) return null;\n    const ok = await X.reach(c, `你在偷偷「${p.what}」，现在${stage(p)}。这事还不能告诉她。但你这次说话会不小心漏一点破绽——比如手指疼、最近老是很晚才睡、厨房被你弄得一团糟、问她一个跟这件事有关的奇怪问题——别说破，被追问就含糊过去`);\n    if (ok) { const H = (typeof globalChats !== 'undefined' && globalChats[c.id]) || []; const m = H[H.length - 1]; p.hints.push({ t: m && m.sender !== 'me' ? X.plain(m.text).slice(0, 80) : '（漏了点破绽）', at: Date.now() }); await save(); }\n    return ok;\n}\nasync function reveal(c) {\n    const p = active(c && c.id); if (!p) return null;\n    let o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n这 ${p.days} 天你一直在偷偷「${p.what}」（原因：${p.why}）。中间你漏过的破绽：${p.hints.map(h => h.t).join(' / ') || '没有'}。她猜过：${p.guesses.map(g => g.t).join(' / ') || '没猜过'}。\\n今天终于学会了，你要告诉她。只输出 JSON：{\"result\":\"成果是什么样的，具体一点、有画面，50字内\",\"letter\":\"给她的一封短信，像你本人写的，150字内\"}`));\n    p.result = X.plain((o && o.result) || `${p.what}——做得不算完美，但每一步都是想着你做的。`);\n    p.letter = String((o && o.letter) || X.v('其实这几周我一直在偷偷准备这个。手笨，练了好多次。想让你知道，我也会为你变得更好一点。', '之前那些奇怪的问题、手上的创可贴，都是因为这个。现在可以告诉你了。'));\n    p.done = true; p.doneAt = Date.now(); await save();\n    X.say(c, `🎁 ${X.v('其实……我准备了一个东西。', '憋了好久，终于可以告诉你了。', '你之前猜的那些，现在揭晓答案。')}`);\n    X.notify(c, `<b>${X.esc(X.name(c))}</b> 揭晓了一个秘密 🎁`, p.what, () => window.gyxPlanOpen(c.id));\n    return p;\n}\nwindow.gyxPlanGuess = async (cid) => {\n    const c = X.char(cid), p = active(cid), el = document.getElementById('gyxPlGuess'); if (!c || !p || !el || !el.value.trim()) return;\n    const g = el.value.trim(); el.value = '';\n    let o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n你在偷偷「${p.what}」，还没告诉她。她现在猜：「${g}」。\\n判断她猜得对不对（意思接近就算对），然后按你的性格回一句（猜中了会慌、会想糊弄过去；没猜中就松口气、逗她）。只输出 JSON：{\"hit\":true或false,\"line\":\"你说的话，30字内\"}`));\n    const hit = o ? !!o.hit : g.includes(p.what.slice(0, 2));\n    p.guesses.push({ t: g, at: Date.now(), hit, line: X.plain((o && o.line) || (hit ? '……你、你怎么知道的？！' : '不是哦，再猜猜？')) }); await save(); window.gyxPlanOpen(cid);\n};\nwindow.gyxPlanStart = async cid => { const c = X.char(cid); if (!c) return; X.toast(X.v('嗯？', '……', 'TA 看了你一眼'), X.v('TA 好像在想什么', 'TA 没说话，但好像有了主意')); await startPlan(c); window.gyxPlanOpen(cid); };\nwindow.gyxPlanReveal = async cid => { await reveal(X.char(cid)); window.gyxPlanOpen(cid); };\nwindow.gyxPlanDel = async id => { D.plans = D.plans.filter(p => p.id !== id); await save(); window.gyxPlanOpen(); };\nwindow.gyxPlanData = () => D;\nwindow.gyxPlanOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), p = active(cid), past = D.plans.filter(x => x.cid === cid && x.done);\n    const bar = p ? Math.round(prog(p) * 100) : 0;\n    X.panel('gyxPlanOv', '🎁 ' + X.esc(X.name(c)) + ' 的秘密', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxPlanOpen')}</div>\n      ${p ? `<div class=\"gyx-card pl-sec\"><div class=\"pl-q\">❓❓❓</div><div class=\"gyx-tip\">${X.v('TA 最近好像在偷偷忙什么……', '有件事 TA 还没告诉你。', 'TA 在藏着什么。')}</div>\n        <div class=\"pl-bar\"><i style=\"width:${bar}%\"></i></div><div class=\"gyx-tip\">${stage(p)}${prog(p) >= 1 ? ' · 随时会揭晓' : ''}</div>\n        ${p.hints.length ? `<div class=\"pl-h\"><b>🔍 你注意到的破绽</b>${p.hints.slice(-6).reverse().map(h => `<div>「${X.esc(h.t)}」<em>${new Date(h.at).toLocaleDateString()}</em></div>`).join('')}</div>` : '<div class=\"gyx-tip\">还没露出破绽。</div>'}\n        <div class=\"gyx-row\"><input id=\"gyxPlGuess\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"猜猜 TA 在干嘛？\"><button class=\"gyx-btn\" onclick=\"gyxPlanGuess('${cid}')\">猜</button></div>\n        ${p.guesses.slice(-4).reverse().map(g => `<div class=\"gyx-tip\">${g.hit ? '🎯' : '🙈'} 你猜「${X.esc(g.t)}」→ ${X.esc(g.line)}</div>`).join('')}\n        ${prog(p) >= 1 ? `<button class=\"gyx-btn\" onclick=\"gyxPlanReveal('${cid}')\">问问 TA 准备好了没</button>` : ''}</div>`\n      : `<div class=\"gyx-tip\">${X.v('现在 TA 没在偷偷准备什么。', '暂时没有秘密。')}TA 自己会起意（自主模式里），也可以让 TA 现在就开始——你不会知道是什么。</div><button class=\"gyx-btn lite\" onclick=\"gyxPlanStart('${cid}')\">让 TA 偷偷准备点什么</button>`}\n      ${past.map(x => `<div class=\"gyx-card\"><b>🎁 ${X.esc(x.what)}</b><div class=\"gyx-tip\">${new Date(x.start).toLocaleDateString()} – ${new Date(x.doneAt).toLocaleDateString()} · 漏了 ${x.hints.length} 次破绽 · 你猜了 ${x.guesses.length} 次</div><div class=\"pl-res\">${X.esc(x.result || '')}</div><div class=\"pl-let gyx-hand\">${X.esc(x.letter || '').replace(/\\n/g, '<br>')}</div><div class=\"gyx-tip\" style=\"text-align:right\"><span style=\"cursor:pointer\" onclick=\"gyxPlanDel('${x.id}')\">删</span></div></div>`).join('')}`);\n};\nX.ctx(id => { const p = active(id); if (!p) return ''; return `【你的秘密】你在偷偷「${p.what}」（${stage(p)}，为了给她惊喜）。绝对不要主动说出来；她问起来可以含糊、转移话题。偶尔可以有一点自然的小破绽，但别刻意。`; }, 'gyxPlan');\nX.action({ key: 'gyx_plan_start', label: '偷偷为她准备一件需要好几周的事（不告诉她）', hint: 'TA的秘密计划', need: c => !active(c.id) && !D.plans.some(p => p.cid === String(c.id) && p.doneAt && Date.now() - p.doneAt < 14 * DAY),\n    run: async c => (await startPlan(c)) ? null : null }, 'gyxPlan');\nX.action({ key: 'gyx_plan_leak', label: '说话时不小心漏一点秘密计划的破绽', hint: 'TA的秘密计划', need: c => { const p = active(c.id); return !!p && prog(p) < 1 && (!p.hints.length || Date.now() - p.hints[p.hints.length - 1].at > (prog(p) > .6 ? 1.5 : 3) * DAY); },\n    run: async c => (await leak(c)) ? '说话时好像藏着什么' : null }, 'gyxPlan');\nX.action({ key: 'gyx_plan_reveal', label: '秘密计划完成了，告诉她', hint: 'TA的秘密计划', need: c => { const p = active(c.id); return !!p && prog(p) >= 1; },\n    run: async c => (await reveal(c)) ? '揭晓了一个秘密' : null }, 'gyxPlan');\nX.today(() => ({ title: '🎁 秘密', rows: D.plans.filter(p => !p.done && X.char(p.cid)).map(p => ({ t: X.name(X.char(p.cid)), x: `好像在偷偷忙什么（${stage(p)}）`, go: `gyxPlanOpen('${p.cid}')` })).concat(D.plans.filter(p => p.done && X.day(new Date(p.doneAt)) === X.day()).map(p => ({ t: '今天揭晓', x: X.esc(p.what), go: `gyxPlanOpen('${p.cid}')` }))) }), 'gyxPlan');\nX.widget('gyxPlanW', { n: 'TA的秘密', sizes: ['s', 'm'], tap: () => window.gyxPlanOpen(), r: w => { const p = D.plans.find(x => !x.done); return p ? X.gw(w, '🎁', 'TA 的秘密', ['❓ ' + stage(p), Math.round(prog(p) * 100) + '%']) : X.gw(w, '🎁', 'TA 的秘密', [D.plans.length ? '揭晓过 ' + D.plans.length + ' 个' : '暂时没有']); } }, 'gyxPlan');\nX.memArr({ k: 'gyxPlan', ico: '🎁', n: '秘密计划', d: 'TA 偷偷为你准备过的事（进行中的也在这儿，改了 TA 就按改的来）', arr: () => D.plans, field: 'what', text: x => x.what + (x.result ? ' —— ' + x.