    X.rnd = (a, b) => a + Math.random() * (b - a);
    X.toast = (a, b) => { try { showToast('', a, b || '', null, null, false); } catch (e) {} };
    X.chars = () => (typeof myCharacters !== 'undefined' ? myCharacters : []).filter(c => c && !c.members);
    X.char = id => X.chars().find(c => String(c.id) === String(id));
