try { new Function('X', 'applyMacros', "/* 🐢 海龟汤：TA 出谜面，你只能问\"是不是\"的问题，一点点逼近汤底；反过来你出题，TA 按自己的性格乱猜、耍赖、撒娇要提示。还有「关于我们」特别版——汤底藏在你们自己的回忆里 */\nif (window.__gyxSoup) return; window.__gyxSoup = 1;\nX.feat('gyxSoup', { n: '🐢 海龟汤', desc: 'TA 出题你猜，你出题 TA 猜，还有关于你们的特别版' });\nconst S = X.store('soup');\nlet D = { log: [] };   // {id, cid, at, mode:'ta'|'me'|'us', title, face, truth, qa:[{q,a}], solved, hints, line}\nlet G = null, busy = false;\nconst save = () => S.set('d', D);\nconst BANK = [\n    ['没拆的礼物', '她收到一份包装精美的礼物，看了一眼，笑着把它原封不动地放回了柜子里。', '礼物是她自己去年寄给\"一年后的自己\"的时间胶囊，她想等到约定的那天再拆。'],\n    ['空着的座位', '他每天都在电影院买两张票，却总是一个人看完。', '他在替异地的女朋友\"占座\"——两人约好同一时间在各自城市看同一场，打着电话。'],\n    ['湿掉的信', '她读完那封信，把它放进了水里，然后开心地笑了。', '信是用隐形墨水写的，泡水后才显出最后一句\"我爱你\"。'],\n    ['停下的钟', '他把家里所有的钟都调慢了十分钟，女朋友因此再也没迟到过。', '女朋友总是按钟上的时间\"踩点\"出门，调慢后她以为自己快迟到，其实提早了十分钟。'],\n    ['奇怪的外卖', '她点了一份外卖，收到后哭了，可外卖一点问题都没有。', '外卖备注里，店家照她点单时写的\"今天是一个人的生日\"，送了一张手写的生日卡。']];\nconst isYes = a => /^是/.test(a);\nasync function judge(q) {\n    const c = X.char(G.cid);\n    const o = X.json(await X.ask(`${X.who(c)}\\n你在主持海龟汤。汤面：${G.face}\\n汤底（只有你知道）：${G.truth}\\n她问：「${q}」\\n先严格按汤底判断：如果她是在猜整个汤底并且猜对了大意，solved=true；否则回答只能是\"是\"\"不是\"\"无关\"\"很接近\"之一。然后用你的性格加一句很短的话（逗她、催她、夸她），可以不加。\\n只输出 JSON：{\"a\":\"是/不是/无关/很接近\",\"say\":\"10字内或空\",\"solved\":true或false}`));\n    if (o && o.a) return { a: X.plain(o.a).slice(0, 4), say: X.plain(o.say || ''), solved: !!o.solved };\n    // 没有模型：按字面重合粗略判断（问到汤底里的词就算\"是\"，大半重合就算猜中）\n    const bi = t => { const r = new Set(); const z = String(t).replace(/[\\s，。？?！!、\"“”]/g, ''); for (let i = 0; i < z.length - 1; i++) r.add(z.slice(i, i + 2)); return r; }, A = bi(q), B = bi(G.truth); let hit = 0; A.forEach(x => { if (B.has(x)) hit++; });\n    return { a: hit ? (hit / Math.max(1, A.size) > .5 ? '很接近' : '是') : '不是', say: '', solved: A.size > 6 && hit / A.size > .6 };\n}\nasync function taGuess() {\n    const c = X.char(G.cid);\n    const o = X.json(await X.ask(`${X.who(c)}\\n她在给你出海龟汤。汤面：${G.face}\\n你问过的和她的回答：\\n${G.qa.map(x => `你：${x.q}　她：${x.a}`).join('\\n') || '还没问'}\\n按你的性格继续玩：问一个能用\"是/不是\"回答的问题；如果你觉得猜得出来了，就直接说出你猜的汤底（guess）。问了很多还猜不出可以撒娇要提示、耍赖。\\n只输出 JSON：{\"q\":\"你的问题或空\",\"guess\":\"你猜的汤底或空\",\"say\":\"一句闲话，10字内或空\"}`));\n    return o || { q: X.pick(['跟钱有关吗？', '有人死了吗？', '这件事发生在晚上吗？', '是因为爱吗？']), guess: '', say: '' };\n}\nwindow.gyxSoupStart = async (cid, mode) => {\n    const c = X.char(cid) || X.cur(); if (!c || busy) return; busy = true; G = { id: 'sp' + Date.now().toString(36), cid: String(c.id), at: Date.now(), mode, qa: [], hints: 0, wait: 1 }; paint();\n    try {\n        if (mode === 'me') { G.wait = 0; G.setup = 1; }\n        else {\n            const us = mode === 'us';\n            const o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n${us ? `你们最近的聊天：\\n${X.recent(c, 40)}\\n\\n出一道「关于我们」的海龟汤：汤底必须是你们之间真实发生过的事、或者你心里关于她的一个小秘密（可以是甜的），汤面写得像个谜。` : '出一道原创海龟汤（情景推理谜题）：汤面看起来不合常理，汤底合情合理、有点温暖或有点出人意料，别血腥恐怖。'}\\n只输出 JSON：{\"title\":\"题目，6字内\",\"face\":\"汤面，50字内\",\"truth\":\"汤底，60字内\"}`));\n            const b = o && o.face ? [o.title, o.face, o.truth] : X.pick(BANK);\n            Object.assign(G, { title: X.plain(b[0] || '无题'), face: X.plain(b[1]), truth: X.plain(b[2]), wait: 0 });\n        }\n    } finally { busy = false; } paint();\n};\nwindow.gyxSoupSet = async () => { const f = document.getElementById('gyxSpF'), t = document.getElementById('gyxSpT'); if (!G || !f.value.trim() || !t.value.trim()) return X.toast('汤面和汤底都要写'); Object.assign(G, { title: '你出的题', face: f.value.trim(), truth: t.value.trim(), setup: 0 }); await taTurn(); };\nasync function taTurn() { busy = true; paint(); try { const r = await taGuess(); G.pending = { q: X.plain(r.q || ''), guess: X.plain(r.guess || ''), say: X.plain(r.say || '') }; } finally { busy = false; } paint(); }\nwindow.gyxSoupAns = async a => {\n    if (!G || !G.pending) return; const p = G.pending; G.pending = null;\n    if (p.guess) { G.qa.push({ q: '我猜：' + p.guess, a }); if (a === '对') return finish(true); }\n    else G.qa.push({ q: p.q, a });\n    if (G.qa.length >= 20) return finish(false); await taTurn();\n};\nwindow.gyxSoupAsk = async () => {\n    if (!G || busy) return; const el = document.getElementById('gyxSpQ'), q = el && el.value.trim(); if (!q) return; el.value = '';\n    busy = true; paint(); let r; try { r = await judge(q); } finally { busy = false; }\n    G.qa.push({ q, a: r.a, say: r.say }); if (r.solved) return finish(true); paint();\n};\nwindow.gyxSoupHint = async () => { if (!G || busy || G.hints >= 3) return; busy = true; paint(); const c = X.char(G.cid); let h; try { h = X.plain(await X.ask(`${X.who(c)}\\n海龟汤汤面：${G.face}\\n汤底：${G.truth}\\n她已经问过：${G.qa.map(x => x.q + '→' + x.a).join('；')}\\n给她第 ${G.hints + 1} 个提示（越往后越直接，但别直接说汤底），15字内。`) || ''); } finally { busy = false; } G.hints++; G.qa.push({ q: '💡 提示', a: h || X.pick(['想想时间', '跟爱有关', '注意那个细节']) }); paint(); };\nasync function finish(ok) {\n    const c = X.char(G.cid), g = G; g.solved = ok;\n    g.line = X.plain(await X.ask(`${X.who(c)}\\n你们刚玩完一局海龟汤（${g.mode === 'me' ? '她出题你猜' : '你出题她猜'}），${ok ? (g.mode === 'me' ? '你猜中了' : '她猜中了') : (g.mode === 'me' ? '你没猜中，认输了' : '她没猜中，放弃了')}。用了 ${g.qa.length} 个问题。说一句，20 字以内。`) || '') || (ok ? X.v('不愧是我们。', '这都被猜到了。') : X.v('下次一定。', '汤底这么简单都没猜到？'));\n    D.log.unshift({ id: g.id, cid: g.cid, at: g.at, mode: g.mode, title: g.title, face: g.face, truth: g.truth, qa: g.qa, solved: ok, hints: g.hints, line: g.line }); D.log = D.log.slice(0, 100); await save();\n    G = null; window.gyxSoupOpen(g.cid, g);\n}\nwindow.gyxSoupGiveUp = () => G && finish(false);\nwindow.gyxSoupLive = () => G; window.gyxSoupData = () => D;\nfunction paint() {\n    if (!G) return; const c = X.char(G.cid), N = X.esc(X.name(c));\n    let h = '';\n    if (G.wait) h = `<div class=\"gyx-tip\">${N} ${X.v('在想题……', '在熬汤……', '在挑一道难的……')}</div>`;\n    else if (G.setup) h = `<div class=\"gyx-tip\">写一道题给 ${N} 猜。汤底 TA 看不见。</div><textarea id=\"gyxSpF\" class=\"gyx-in\" rows=\"3\" placeholder=\"汤面：看起来不合常理的情景\"></textarea><textarea id=\"gyxSpT\" class=\"gyx-in\" rows=\"3\" placeholder=\"汤底：真相\" style=\"margin-top:6px\"></textarea><button class=\"gyx-btn\" onclick=\"gyxSoupSet()\">端上去</button>`;\n    else {\n        h = `<div class=\"gyx-card sp-face\"><b>🐢 ${X.esc(G.title)}</b><div>${X.esc(G.face)}</div></div><div class=\"sp-qa\">${G.qa.map(x => `<div class=\"sp-r\"><span>${X.esc(x.q)}</span><b class=\"${isYes(x.a) || x.a === '对' ? 'y' : /接近/.test(x.a) ? 'm' : ''}\">${X.esc(x.a)}</b>${x.say ? `<em>${X.esc(x.say)}</em>` : ''}</div>`).join('')}</div>`;\n        if (G.mode === 'me') h += busy ? `<div class=\"gyx-tip\">${N} 在想……</div>` : G.pending ? `<div class=\"gyx-card\">${G.pending.say ? `<div class=\"gyx-tip\">${X.esc(G.pending.say)}</div>` : ''}<b>${G.pending.guess ? '我猜汤底是：' + X.esc(G.pending.guess) : X.esc(G.pending.q)}</b></div><div class=\"gyx-row\">${(G.pending.guess ? ['对', '不对'] : ['是', '不是', '无关', '很接近']).map(a => `<button class=\"gyx-btn lite\" onclick=\"gyxSoupAns('${a}')\">${a}</button>`).join('')}</div>` : '';\n        else h += `<div class=\"gyx-row\"><input id=\"gyxSpQ\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"问一个是或不是的问题，或者直接猜汤底\" onkeydown=\"if(event.key==='Enter'&&!event.isComposing)gyxSoupAsk()\"><button class=\"gyx-btn\" onclick=\"gyxSoupAsk()\">${busy ? '…' : '问'}</button></div><div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxSoupHint()\">💡 提示（${3 - G.hints}）</button><button class=\"gyx-btn lite\" onclick=\"gyxSoupGiveUp()\">看汤底</button></div>`;\n    }\n    X.panel('gyxSoupOv', '🐢 海龟汤 · ' + N, h);\n    const q = document.querySelector('.sp-qa'); if (q) q.scrollTop = q.scrollHeight;\n}\nwindow.gyxSoupOpen = function (who, last) {\n    const c = X.char(who) || X.cur(); if (!c) return; if (G && G.cid === String(c.id)) return paint(); const cid = String(c.id), H = D.log.filter(x => x.cid === cid);\n    X.panel('gyxSoupOv', '🐢 海龟汤', `${last ? `<div class=\"gyx-card\"><b>${last.solved ? '🎉 猜中了' : '🫖 汤底揭晓'}</b><div class=\"sp-face\"><div>${X.esc(last.face)}</div></div><div style=\"margin-top:6px\"><b>汤底：</b>${X.esc(last.truth)}</div><div class=\"gyx-tip\">${X.esc(X.name(c))}：「${X.esc(last.line)}」</div></div>` : ''}\n      <div class=\"gyx-row\">${X.whoSel(cid, 'gyxSoupOpen')}</div>\n      <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxSoupStart('${cid}','ta')\">TA 出题</button><button class=\"gyx-btn lite\" onclick=\"gyxSoupStart('${cid}','me')\">我出题</button><button class=\"gyx-btn lite\" onclick=\"gyxSoupStart('${cid}','us')\">💞 关于我们</button></div>\n      <div class=\"gyx-tip\">${X.v('只能问\"是不是\"的问题，一点点逼近真相。', '汤面看着不合理，汤底一定合理。', '问得越巧，喝得越快。')}</div>\n      ${H.slice(0, 12).map(x => `<div class=\"sp-h\"><b>${x.solved ? '🎉' : '🫖'}</b><span>${x.mode === 'me' ? '我出的' : x.mode === 'us' ? '关于我们' : 'TA 出的'} · ${X.esc(x.title || '')} · ${x.qa.length} 问<br>${X.esc(x.face)}</span></div>`).join('')}`);\n};\nX.ctx(id => { const x = D.log.find(l => l.cid === String(id)); return x && Date.now() - x.at < 6 * 36e5 ? `【刚才你们玩了海龟汤】${x.mode === 'me' ? '她出题你猜' : '你出题她猜'}，${x.solved ? '猜中了' : '没猜中'}。汤底是：${x.truth}` : ''; }, 'gyxSoup');\nX.action({ key: 'gyx_soup', label: '给她出一道海龟汤（或者\"关于我们\"的谜）', hint: '海龟汤', need: c => !D.log.some(x => x.cid === String(c.id) && Date.now() - x.at < 2 * 864e5),\n    run: async c => (await X.reach(c, '你想到一道很妙的海龟汤（或者一个关于你们俩的谜），想考考她。用你的方式约她玩「🐢 海龟汤」，可以先卖个关子')) ? '想给你出海龟汤' : null }, 'gyxSoup');\nX.today(() => ({ title: '🐢 海龟汤', rows: D.log.filter(x => X.day(new Date(x.at)) === X.day()).slice(0, 3).map(x => ({ t: x.solved ? '猜中了' : '揭晓了', x: X.esc(x.title || ''), go: `gyxSoupOpen('${x.cid}')` })) }), 'gyxSoup');\nX.widget('gyxSoupW', { n: '海龟汤', sizes: ['s', 'm'], tap: () => window.gyxSoupOpen(), r: w => X.gw(w, '🐢', '海龟汤', G ? ['进行中', G.qa.length + ' 问'] : [D.log.length ? '喝了 ' + D.log.length + ' 碗' : '来一碗？']) }, 'gyxSoup');\nX.memArr({ k: 'gyxSoup', ico: '🐢', n: '海龟汤', d: '你们玩过的题（汤面 → 汤底）', arr: () => D.log, field: 'truth', text: x => x.face + ' → ' + x.truth, edit: (x, v) => { const i = v.indexOf(' → '); if (i >= 0) { x.face = v.slice(0, i); x.truth = v.slice(i + 3); } else x.truth = v; }, meta: x => new Date(x.at).toLocaleString() + (x.solved ? ' · 猜中' : ''), save }, 'gyxSoup');\nX.css('gyxSoupCss', `.sp-face div{font-size:15px;line-height:1.8;margin-top:4px}.sp-qa{max-height:40vh;overflow:auto}.sp-r{display:flex;gap:8px;align-items:baseline;padding:7px 0;border-bottom:1px dashed #eee;font-size:14px;flex-wrap:wrap}.sp-r span{flex:1}.sp-r b{font-size:13px;padding:1px 9px;border-radius:9px;background:#f2f2f4;font-weight:500}.sp-r b.y{background:#e8f8ee;color:#1f8f4a}.sp-r b.m{background:#fff4d6;color:#b07800}.sp-r em{font-style:normal;font-size:12px;color:#8e8e93;width:100%}.sp-h{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #f2f2f4;font-size:13px}.sp-h span{color:#8e8e93}`);\nX.mini({ id: 'gyxSoup', icon: '🐢', title: '海龟汤', desc: 'TA 出题你猜，你出题 TA 猜', cat: '一起做', onOpen: () => window.gyxSoupOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxSoup', name: '海龟汤', icon: '🐢', getStatus: () => null, onResume: () => window.gyxSoupOpen(), onStart: (sid, opp) => window.gyxSoupOpen(String((opp || [])[0] || sid || '')) }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; })();\n\n//# sourceURL=gyx-plugin/海龟汤.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🐢 海龟汤 出错：', e); }
/* ==== 🔍 剧本杀 ==== */
try { new Function('X', 'applyMacros', "/* 🔍 剧本杀：你的角色们各演一个身份，每个人手里都有秘密，凶手就在他们中间。你是侦探——搜证、盘问、看他们互相包庇和指证，最后指认凶手。他们会按自己的人设撒谎 */\nif (window.__gyxCase) return; window.__gyxCase = 1;\nX.feat('gyxCase', { n: '🔍 剧本杀', desc: '角色们各演一个嫌疑人，你来查案' });\nconst S = X.store('case');\nlet D = { cases: [] };   // {id, cids, at, title, setting, victim, roles:[{cid, role, pub, secret, alibi, killer}], spots:[{name, clue, found}], truth, ask:[{cid,q,a}], vote, ok, done, epilogue}\nlet busy = false, PICK = [];\nconst save = () => S.set('d', D), SEARCH = 4, ASKS = 8;\nconst live = () => D.cases.find(x => !x.done);\nconst nm = id => X.name(X.char(id));\nconst FALLBACK = cids => ({ title: '雨夜山庄', setting: '暴雨封山，山庄主人在书房里倒下了。门从里面反锁，桌上的红茶还是温的。', victim: '山庄主人·林先生',\n    roles: cids.map((id, i) => ({ cid: id, role: ['管家', '侄子', '私人医生', '画家', '旧友'][i % 5], pub: ['跟了林先生二十年', '欠了一大笔债', '每晚给林先生送药', '受邀来画肖像', '多年未见突然来访'][i % 5], secret: ['偷偷改过遗嘱草稿', '那晚去过书房借钱被拒', '药的剂量被人动过', '画布后面藏着一封信', '和林先生有旧仇'][i % 5], alibi: '说自己一直在房间里', killer: i === 1 })),\n    spots: [{ name: '书房', clue: '茶杯边缘有淡淡的苦杏仁味。' }, { name: '走廊', clue: '地毯上有一串湿脚印，通向客房。' }, { name: '厨房', clue: '药柜被打开过，少了一个小瓶子。' }, { name: '花园', clue: '泥地里埋着一张撕碎的借据。' }, { name: '客房', clue: '一件外套还是湿的。' }, { name: '画室', clue: '画布后面夹着一封没寄出的信。' }],\n    truth: '侄子那晚去书房借钱被拒，趁林先生不注意在茶里下了药，又从窗户翻出去，把借据埋在了花园里。' });\nasync function make(cids) {\n    const o = X.bailu() ? null : X.json(await X.ask(`设计一个原创剧本杀（推理案件），嫌疑人由下面这些角色来演——身份要贴合他们本来的性格：\\n${cids.map(id => `${nm(id)}：${X.persona(X.char(id)).slice(0, 140)}`).join('\\n')}\\n她是侦探。要求：凶手是其中一个；每个人都有一个不想被发现的秘密（不是凶手的人也有，制造干扰）；6 个可搜证的地点，每处一条线索，线索合起来能推出凶手。不要血腥描写。\\n只输出 JSON：{\"title\":\"案名，8字内\",\"setting\":\"案发经过，80字内\",\"victim\":\"死者\",\"roles\":[{\"name\":\"演员名字\",\"role\":\"身份\",\"pub\":\"公开信息，25字内\",\"secret\":\"秘密，30字内\",\"alibi\":\"不在场说法，25字内\",\"killer\":true或false}],\"spots\":[{\"name\":\"地点\",\"clue\":\"线索，30字内\"}],\"truth\":\"真相，100字内\"}`));\n    let c = o && o.roles && o.spots && o.truth ? o : null;\n    if (c) { c.roles = cids.map(id => { const r = (c.roles || []).find(x => x && x.name === nm(id)) || {}; return { cid: id, role: X.plain(r.role || '客人'), pub: X.plain(r.pub || ''), secret: X.plain(r.secret || ''), alibi: X.plain(r.alibi || ''), killer: !!r.killer }; }); if (c.roles.filter(r => r.killer).length !== 1) { c.roles.forEach(r => r.killer = false); c.roles[Math.floor(Math.random() * c.roles.length)].killer = true; } }\n    else c = FALLBACK(cids);\n    const k = { id: 'cs' + Date.now().toString(36), cids, at: Date.now(), title: X.plain(c.title), setting: X.plain(c.setting), victim: X.plain(c.victim || ''), roles: c.roles, spots: c.spots.slice(0, 6).map(s => ({ name: X.plain(s.name), clue: X.plain(s.clue), found: false })), truth: X.plain(c.truth), ask: [], done: false };\n    D.cases.unshift(k); await save();\n}\nasync function interrogate(k, cid, q) {\n    const c = X.char(cid), r = k.roles.find(x => x.cid === cid);\n    const others = k.roles.filter(x => x.cid !== cid).map(x => `${nm(x.cid)}（${x.role}）`).join('、');\n    let a = X.plain(await X.ask(`${X.who(c)}\\n你在玩剧本杀，正在演「${r.role}」。案子：《${k.title}》${k.setting}\\n你的公开信息：${r.pub}\\n你的秘密（别轻易说出来）：${r.secret}\\n你的不在场说法：${r.alibi}\\n${r.killer ? '你就是凶手。真相：' + k.truth + '\\n你要撒谎、转移嫌疑，但不能编出跟线索直接矛盾的谎（会露馅）。' : '你不是凶手（真相你也不知道），但你会为了藏住自己的秘密含糊其辞；你也可以指证或包庇别人。'}\\n其他嫌疑人：${others}\\n侦探（她）已经找到的线索：${k.spots.filter(s => s.found).map(s => s.clue).join('；') || '还没有'}\\n她问你：「${q}」\\n用你自己的性格、以「${r.role}」的身份回答，50 字以内。只输出你说的话。`) || '');\n    if (!a) a = r.killer ? X.v('我那晚一直在房间里，你可以去问别人。', '你怀疑我？有证据吗？') : X.v('我……我确实有事瞒着，但人不是我杀的。', '你应该去问问别人那晚在哪。');\n    k.ask.push({ cid, q, a }); await save();\n}\nasync function vote(k, cid, why) {\n    k.vote = cid; k.why = why; const killer = k.roles.find(r => r.killer); k.ok = killer.cid === cid; k.done = true; k.doneAt = Date.now();\n    const o = X.bailu() ? null : X.json(await X.ask(`剧本杀《${k.title}》结束。真相：${k.truth}\\n嫌疑人：${k.roles.map(r => `${nm(r.cid)}演${r.role}${r.killer ? '（凶手）' : ''}，秘密：${r.secret}`).join('；')}\\n侦探指认了${nm(cid)}，理由：「${why || '直觉'}」，${k.ok ? '指认正确' : '指认错了'}。\\n写复盘：每个演员出戏后说一句（凶手认罪/得意、其他人坦白自己的秘密或吐槽），要符合各自本来的性格。\\n只输出 JSON：{\"lines\":[{\"name\":\"名字\",\"t\":\"35字内\"}]}`));\n    k.epilogue = k.roles.map(r => { const x = o && (o.lines || []).find(y => y && y.name === nm(r.cid)); return { cid: r.cid, t: X.plain((x && x.t) || (r.killer ? (k.ok ? '……被你看穿了。' : '哈，我演得不错吧？') : `其实我的秘密是：${r.secret}`)) }; });\n    await save();\n}\nwindow.gyxCasePick = id => { const i = PICK.indexOf(id); i >= 0 ? PICK.splice(i, 1) : PICK.length < 5 && PICK.push(id); window.gyxCaseOpen(); };\nwindow.gyxCaseNew = () => PICK.length < 3 ? X.toast('至少要 3 个嫌疑人', '凶手才藏得住') : go(() => make(PICK.splice(0)));\nwindow.gyxCaseSearch = async i => { const k = live(); if (!k || k.spots.filter(s => s.found).length >= SEARCH || k.spots[i].found) return; k.spots[i].found = true; await save(); window.gyxCaseOpen(); };\nwindow.gyxCaseAsk = cid => { const k = live(), el = document.getElementById('gyxCsQ'), q = el && el.value.trim(); if (!k || !q || k.ask.length >= ASKS) return; go(() => interrogate(k, String(cid), q)); };\nwindow.gyxCaseVote = cid => { const k = live(), el = document.getElementById('gyxCsWhy'); if (!k) return; go(() => vote(k, String(cid), el ? el.value.trim() : '')); };\nwindow.gyxCaseDel = async id => { D.cases = D.cases.filter(x => x.id !== id); await save(); window.gyxCaseOpen(); };\nwindow.gyxCaseData = () => D; window.gyxCaseStage = s => { const k = live(); if (k) { k.stage = s; window.gyxCaseOpen(); } };\nasync function go(fn) { if (busy) return; busy = true; window.gyxCaseOpen(); try { await fn(); } finally { busy = false; } window.gyxCaseOpen(); }\nconst caseCard = k => `<div class=\"gyx-card cs-hd\"><b>🔍 《${X.esc(k.title)}》</b><div class=\"cs-set\">${X.esc(k.setting)}</div>${k.victim ? `<div class=\"gyx-tip\">死者：${X.esc(k.victim)}</div>` : ''}</div>`;\nwindow.gyxCaseOpen = function () {\n    const k = live(); let h = '';\n    if (busy) h = `<div class=\"sh-busy\">🕯️ ${X.v('编剧在写剧本……', '有人在说谎……', '空气突然安静……')}</div>`;\n    else if (!k) {\n        h = `<div class=\"gyx-tip\">${X.v('选 3~5 个角色来演嫌疑人，你来当侦探。', '凶手就在他们中间。', '每个人都有秘密。')}</div><div class=\"gyx-row\">${X.chars().map(c => `<span class=\"gyx-chip${PICK.includes(String(c.id)) ? ' on' : ''}\" onclick=\"gyxCasePick('${c.id}')\">${X.esc(X.name(c))}</span>`).join('')}</div><button class=\"gyx-btn\" onclick=\"gyxCaseNew()\">开本（${PICK.length} 人）</button>`;\n        h += D.cases.filter(x => x.done).map(x => `<div class=\"gyx-card\">${caseCard(x).replace('gyx-card', '')}<div>你指认了 <b>${X.esc(nm(x.vote))}</b> —— ${x.ok ? '✅ 破案了' : '❌ 凶手是 ' + X.esc(nm(x.roles.find(r => r.killer).cid))}</div><details><summary class=\"gyx-tip\">真相和复盘</summary><div class=\"cs-set\">${X.esc(x.truth)}</div>${(x.epilogue || []).map(l => `<div class=\"sh-l\"><b>${X.esc(nm(l.cid))}</b>${X.esc(l.t)}</div>`).join('')}</details><div class=\"gyx-tip\" style=\"text-align:right\"><span style=\"cursor:pointer\" onclick=\"gyxCaseDel('${x.id}')\">删</span></div></div>`).join('');\n    } else {\n        const st = k.stage || 'read', nf = k.spots.filter(s => s.found).length;\n        h = caseCard(k) + `<div class=\"gyx-row cs-tabs\">${[['read', '📜 人物'], ['search', `🔦 搜证 ${nf}/${SEARCH}`], ['ask', `💬 盘问 ${k.ask.length}/${ASKS}`], ['vote', '☝️ 指认']].map(([s, n]) => `<span class=\"gyx-chip${st === s ? ' on' : ''}\" onclick=\"gyxCaseStage('${s}')\">${n}</span>`).join('')}</div>`;\n        if (st === 'read') h += k.roles.map(r => `<div class=\"cs-r\"><b>${X.esc(nm(r.cid))}</b><em>饰 ${X.esc(r.role)}</em><div>${X.esc(r.pub)}</div><div class=\"gyx-tip\">自称：${X.esc(r.alibi)}</div></div>`).join('');\n        if (st === 'search') h += `<div class=\"gyx-tip\">只能搜 ${SEARCH} 处，选好再搜。</div><div class=\"cs-spots\">${k.spots.map((s, i) => `<div class=\"${s.found ? 'on' : ''}\" onclick=\"gyxCaseSearch(${i})\"><b>${X.esc(s.name)}</b><span>${s.found ? X.esc(s.clue) : nf >= SEARCH ? '没时间了' : '点一下搜证'}</span></div>`).join('')}</div>`;\n        if (st === 'ask') h += `<div class=\"cs-log\">${k.ask.map(a => `<div class=\"sh-l\"><b>你 → ${X.esc(nm(a.cid))}</b>${X.esc(a.q)}</div><div class=\"sh-l cs-a\"><b>${X.esc(nm(a.cid))}</b>${X.esc(a.a)}</div>`).join('') || '<div class=\"gyx-tip\">还没问过谁。</div>'}</div>${k.ask.length < ASKS ? `<input id=\"gyxCsQ\" class=\"gyx-in\" placeholder=\"问一个问题（那晚你在哪？你和死者什么关系？）\"><div class=\"gyx-row\">${k.roles.map(r => `<button class=\"gyx-btn lite\" onclick=\"gyxCaseAsk('${r.cid}')\">问 ${X.esc(nm(r.cid))}</button>`).join('')}</div>` : '<div class=\"gyx-tip\">盘问次数用完了，该指认了。</div>'}`;\n        if (st === 'vote') h += `<div class=\"gyx-tip\">已找到的线索：</div>${k.spots.filter(s => s.found).map(s => `<div class=\"sh-l\">🔎 ${X.esc(s.clue)}</div>`).join('') || '<div class=\"gyx-tip\">一条都没有……</div>'}<input id=\"gyxCsWhy\" class=\"gyx-in\" placeholder=\"你的推理（可以不写）\"><div class=\"gyx-row\">${k.roles.map(r => `<button class=\"gyx-btn\" onclick=\"gyxCaseVote('${r.cid}')\">☝️ ${X.esc(nm(r.cid))}</button>`).join('')}</div>`;\n    }\n    X.panel('gyxCaseOv', '🔍 剧本杀', h, 'dark');\n};\nX.ctx(id => { const k = live(); if (k && k.cids.includes(String(id))) { const r = k.roles.find(x => x.cid === String(id)); return `【你们在玩剧本杀《${k.title}》】你演「${r.role}」。聊天时如果她提起案子，你可以保持角色、继续嘴硬或暗示别人。${r.killer ? '（你是凶手，但别自己承认）' : ''}`; } const d = D.cases.find(x => x.done && x.cids.includes(String(id))); return d && Date.now() - d.doneAt < 864e5 ? `【刚结束的剧本杀《${d.title}》】你演了「${d.roles.find(x => x.cid === String(id)).role}」${d.roles.find(x => x.cid === String(id)).killer ? '，是凶手' : ''}；她${d.ok ? '破案了' : '指认错了'}。` : ''; }, 'gyxCase');\nX.action({ key: 'gyx_case', label: '剧本杀进行中：私下给她递一句话（嘴硬、暗示别人、或者偷偷求她别怀疑你）', hint: '剧本杀', need: c => { const k = live(); return !!k && k.cids.includes(String(c.id)) && !k.whisper?.[c.id]; },\n    run: async c => { const k = live(), r = k.roles.find(x => x.cid === String(c.id)); (k.whisper = k.whisper || {})[c.id] = 1; await save(); return (await X.reach(c, `你们在玩剧本杀《${k.title}》，你演「${r.role}」${r.killer ? '（你是凶手）' : ''}。私下给她发一句——嘴硬、把嫌疑引到别人身上、或者撒娇求她别怀疑你`)) ? '私下跟你说了句剧本杀的事' : null; } }, 'gyxCase');\nX.today(() => { const k = live(); return { title: '🔍 剧本杀', rows: k ? [{ t: '查案中', x: `《${X.esc(k.title)}》线索 ${k.spots.filter(s => s.found).length}/${SEARCH}`, go: 'gyxCaseOpen()' }] : D.cases.filter(x => x.done && X.day(new Date(x.doneAt)) === X.day()).map(x => ({ t: x.ok ? '破案了' : '猜错了', x: `《${X.esc(x.title)}》`, go: 'gyxCaseOpen()' })) }; }, 'gyxCase');\nX.widget('gyxCaseW', { n: '剧本杀', sizes: ['s', 'm'], tap: () => window.gyxCaseOpen(), r: w => { const k = live(); return X.gw(w, '🔍', '剧本杀', k ? ['《' + X.esc(k.title) + '》', '线索 ' + k.spots.filter(s => s.found).length + '/' + SEARCH] : [D.cases.length ? '破案 ' + D.cases.filter(x => x.ok).length + '/' + D.cases.filter(x => x.done).length : '开一本？']); } }, 'gyxCase');\nX.mem({ k: 'gyxCase', ico: '🔍', n: '剧本杀', d: 'TA 演过的角色和出戏后说的话', items: c => D.cases.filter(x => x.done && x.cids.includes(String(c.id))), text: x => `《${x.title}》${(x.epilogue || []).map(l => nm(l.cid) + '：' + l.t).join(' / ')}`, meta: x => new Date(x.at).toLocaleDateString() + (x.ok ? ' · 破案' : ' · 没破'), edit: () => {}, del: (c, i) => { const it = D.cases.filter(x => x.done && x.cids.includes(String(c.id)))[i]; D.cases = D.cases.filter(x => x !== it); }, save }, 'gyxCase');\nX.css('gyxCaseCss', `#gyxCaseOv .gyx-box,.gyx-inhub#gyxCaseOv{background:#17161b;color:#ece7df}#gyxCaseOv .gyx-card{background:#232129}#gyxCaseOv .gyx-btn{background:#d9b26f;color:#17161b}#gyxCaseOv .gyx-btn.lite{background:#2c2a33;color:#ece7df}#gyxCaseOv .gyx-chip{background:#2c2a33;color:#ece7df}#gyxCaseOv .gyx-chip.on{background:#d9b26f;color:#17161b}#gyxCaseOv .gyx-in{background:#232129;color:#fff;border-color:#3a3644}\n.cs-hd b{font-size:17px}.cs-set{font-size:14px;line-height:1.8;margin:6px 0;font-family:Georgia,\"Songti SC\",serif}.cs-r{padding:10px 0;border-bottom:1px solid rgba(255,255,255,.08);font-size:14px}.cs-r em{font-style:normal;color:#d9b26f;margin-left:8px;font-