st.contains('open')) return;\n        ov.classList.add('crack'); try { navigator.vibrate && navigator.vibrate(30); } catch (er) {}\n        snap();\n        setTimeout(() => ov.classList.add('open'), 450);\n        setTimeout(() => ov.classList.add('read'), 1400);\n    });\n    window.gyxLetterClose = () => { ov.classList.add('out'); setTimeout(() => { ov.remove(); if (done) done(); }, 400); };\n}\nfunction snap() { try { const a = new (window.AudioContext || window.webkitAudioContext)(), n = a.createBufferSource(), b = a.createBuffer(1, a.sampleRate * .08, a.sampleRate), d = b.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 3); n.buffer = b; const f = a.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 1400; n.connect(f); f.connect(a.destination); n.start(); } catch (e) {} }\nwindow.gyxLetterShow = (cid, item, done) => show(X.char(cid), item, done);\nfunction hook() {\n    const f = window.openDiaryDetail; if (typeof f !== 'function' || f.__gyxLt) return;\n    const w = function (id) {\n        try {\n            const tab = typeof currentDiaryTab !== 'undefined' ? currentDiaryTab : '', cid = typeof currentDiaryCharId !== 'undefined' ? currentDiaryCharId : null;\n            const c = X.char(cid);\n            if (tab === 'letter' && c && c.diaryData) {\n                const it = (c.diaryData.letters || []).find(x => x.id === id);\n                if (it && it.author !== 'user' && X.on('gyxLetter') && (C.every || !C.seen[id])) {\n                    C.seen[id] = Date.now(); S.set('c', C);\n                    const args = arguments, self = this;\n                    show(c, it, () => f.apply(self, args));\n                    return;\n                }\n            }\n        } catch (e) {}\n        return f.apply(this, arguments);\n    };\n    w.__gyxLt = true; window.openDiaryDetail = w;\n}\nwindow.gyxLetterOpen = function () {\n    X.panel('gyxLtSet', '💌 拆信仪式', `<div class=\"gyx-tip\">TA 寄来的信，第一次打开时会先看到一个封着火漆的信封，按一下火漆印掰开，信纸滑出来。每个角色的火漆颜色不一样。</div>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${C.every ? 'checked' : ''} onchange=\"gyxLetterCfg(this.checked)\"> 每次打开信都拆一遍（不勾＝只有第一次）</label>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxLetterDemo()\">试拆一封</button></div>`);\n};\nwindow.gyxLetterCfg = v => { C.every = v; S.set('c', C); };\nwindow.gyxLetterDemo = () => { const c = X.cur(); const ov = document.getElementById('gyxLtSet'); if (ov) ov.remove(); show(c, { title: '给你的信', content: '见字如面。\\n\\n今天路过一家花店，看到一束很像你的花，就想给你写封信。\\n不用回也没关系，我只是想让你知道，我在想你。', date: Date.now() }); };\nX.css('gyxLtCss', `\n.lt-ov{position:fixed;inset:0;z-index:100001;background:radial-gradient(ellipse at 50% 40%,rgba(60,45,35,.55),rgba(20,15,10,.82));display:flex;align-items:center;justify-content:center;animation:ltIn .4s both;padding:16px;box-sizing:border-box}\n.lt-ov.out{opacity:0;transition:opacity .4s}@keyframes ltIn{from{opacity:0}}\n.lt-stage{position:relative;width:min(420px,92vw);display:flex;flex-direction:column;align-items:center;gap:22px;transition:transform .8s cubic-bezier(.4,0,.2,1),opacity .6s}\n.lt-ov.read .lt-stage{transform:translateY(55vh);opacity:0}\n.lt-env{position:relative;width:100%;aspect-ratio:16/10;animation:ltDrop .8s cubic-bezier(.2,1.2,.3,1) both}\n@keyframes ltDrop{from{transform:translateY(-40px) rotate(-4deg);opacity:0}to{transform:rotate(-1deg);opacity:1}}\n.lt-back{position:absolute;inset:0;border-radius:6px;background:#e6d6b8;box-shadow:0 20px 50px rgba(0,0,0,.35)}\n.lt-front{position:absolute;inset:0;border-radius:6px;z-index:3;display:flex;flex-direction:column;justify-content:flex-end;padding:0 18px 12px;background:#efe3cc;clip-path:polygon(0 0,50% 58%,100% 0,100% 100%,0 100%)}\n.lt-addr{font-size:22px;color:#5b4632}.lt-from{font-size:11px;color:#8b7355;letter-spacing:.1em}\n.lt-flap{position:absolute;left:0;right:0;top:0;height:60%;background:#e2d0ad;clip-path:polygon(0 0,100% 0,50% 100%);transform-origin:top;z-index:4;transition:transform .7s cubic-bezier(.5,0,.3,1),z-index 0s .35s}\n.lt-ov.open .lt-flap{transform:rotateX(180deg);z-index:1}\n.lt-paper{position:absolute;left:6%;right:6%;top:4%;height:90%;background:#fffdf6;border-radius:3px;z-index:2;background-image:linear-gradient(transparent 21px,#eadfca 22px);background-size:100% 22px;opacity:0;transition:transform 1s cubic-bezier(.3,1,.4,1) .15s,opacity .2s}\n.lt-ov.open .lt-paper{opacity:1;transform:translateY(-55%)}\n.lt-wax{position:absolute;left:50%;top:58%;width:64px;height:64px;margin:-32px 0 0 -32px;border-radius:50%;background:radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--w) 60%,#fff),var(--w) 60%);box-shadow:0 4px 10px rgba(0,0,0,.35),inset 0 -3px 6px rgba(0,0,0,.3);z-index:5;cursor:pointer;display:flex;align-items:center;justify-content:center;color:rgba(255,255,255,.75);font-size:26px;font-family:\"Noto Serif SC\",serif;animation:ltPulse 2s ease-in-out infinite}\n.lt-wax span{text-shadow:0 -1px 0 rgba(0,0,0,.35)}.lt-wax i{position:absolute;inset:0;border-radius:50%;opacity:0}\n@keyframes ltPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}\n.lt-ov.crack .lt-wax{animation:none;background:none;box-shadow:none}.lt-ov.crack .lt-wax span{opacity:0}\n.lt-ov.crack .lt-wax i{opacity:1;background:radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--w) 60%,#fff),var(--w) 60%);transition:transform .6s cubic-bezier(.3,.7,.4,1),opacity .6s .3s}\n.lt-ov.crack .lt-wax i.l{clip-path:polygon(0 0,55% 0,40% 50%,50% 100%,0 100%);transform:translate(-26px,30px) rotate(-40deg);opacity:0}.lt-ov.crack .lt-wax i.r{clip-path:polygon(55% 0,100% 0,100% 100%,50% 100%,40% 50%);transform:translate(26px,34px) rotate(35deg);opacity:0}\n.lt-hint{color:#f3e8d6;font-size:13px;letter-spacing:.2em;animation:ltPulse 2s infinite}.lt-ov.crack .lt-hint{opacity:0;transition:opacity .3s}\n.lt-sheet{position:absolute;left:50%;top:50%;width:min(440px,90vw);max-height:84vh;overflow:auto;box-sizing:border-box;padding:28px 26px 20px;background:#fffdf6;border-radius:4px;box-shadow:0 30px 70px rgba(0,0,0,.4);color:#3b3024;background-image:linear-gradient(transparent 31px,#eadfca 32px);background-size:100% 32px;background-position:0 18px;transform:translate(-50%,-30%) scale(.9);opacity:0;pointer-events:none;transition:transform .9s cubic-bezier(.2,1,.3,1) .1s,opacity .5s .1s}\n.lt-ov.read .lt-sheet{transform:translate(-50%,-50%) rotate(-.6deg);opacity:1;pointer-events:auto}\n.lt-h{font-size:26px;text-align:center;margin-bottom:6px}.lt-body{font-size:21px;line-height:32px;word-break:break-all}.lt-sig{text-align:right;font-size:21px;margin-top:12px;line-height:1.4}.lt-sig small{font-size:13px;color:#a09380}\n.lt-done{display:flex;justify-content:center;margin-top:16px}\n`);\nX.mini({ id: 'gyxLetter', icon: '💌', title: '拆信仪式', desc: 'TA 寄来的信变成真的信封：火漆印、掰开、信纸滑出来、手写字', onOpen: () => window.gyxLetterOpen() });\n(async () => { C = Object.assign(C, await S.get('c', {})); C.seen = C.seen || {}; hook(); setInterval(hook, 3000); })();\n\n//# sourceURL=gyx-plugin/拆信仪式.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 💌 拆信仪式 出错：', e); }
/* ==== 📓 交换日记本 ==== */
try { new Function('X', 'applyMacros', "/* 📓 交换日记本：一本你们轮流写的本子——手写字、纸张、胶带和贴纸；你写完一页，TA 过一阵接着写 */\nif (window.__gyxJournal) return; window.__gyxJournal = 1;\nX.feat('gyxJournal', { n: '📓 交换日记本', desc: '你们轮流写的本子：手写字、纸张、胶带、贴纸；你写完 TA 过一阵接着写' });\nconst S = X.store('journal');\nlet D = { books: {}, cfg: { minH: 1, maxH: 10 } };   // books[cid] = { pages:[{by, text, at, deco, stickers}], pending:{at} , paper }\nconst PAPERS = [['格子', 'grid'], ['横线', 'line'], ['牛皮纸', 'kraft'], ['点点', 'dot'], ['空白', 'plain']];\nconst TAPES = ['#f7c5cc', '#c9e4ff', '#d6f5d6', '#ffe8a8', '#e3d4ff', '#ffd6b8'];\nconst STK = ['🌷', '⭐', '🍓', '☁️', '🐱', '🌙', '💌', '🍀', '🎀', '☕', '🌻', '🫧', '🐻', '🍰', '✨', '💗'];\nconst book = cid => (D.books[cid] = D.books[cid] || { pages: [], pending: null, paper: 'grid' });\nlet CID = '', PG = -1, EDIT = null;\nasync function taWrite(c) {\n    const b = book(String(c.id)); const last = b.pages.slice(-4).map(p => `${p.by === 'me' ? X.me(c) : '你'}写的：\\n${p.text}`).join('\\n\\n');\n    if (X.bailu()) return X.cards(['日记', '信', '聊天'], c, 4).join('\\n') || '今天也想你。';\n    const r = await X.ask(`${X.who(c)}\\n你们有一本交换日记本，轮流写。最近几页：\\n\\n${last || '（这是第一页）'}\\n\\n最近的聊天：\\n${X.recent(c, 10)}\\n\\n轮到你写了。像写在纸上的日记：先回应她上一页写的（接她的话、回答她的问题），再写写你这几天的事和想法，可以问她一个问题留给她下一页回答。口语，真诚，80~260 字，分几段。不要标题，不要动作描写的括号。只输出正文。`);\n    return r ? r.replace(/^[\"“]|[\"”]$/g, '').trim() : null;\n}\nasync function taTurn(cid) {\n    const c = X.char(cid); if (!c) return;\n    const t = await taWrite(c); if (!t) return;\n    const b = book(cid); b.pending = null;\n    b.pages.push({ by: 'ta', text: t, at: Date.now(), tape: X.pick(TAPES), stickers: [X.pick(STK)].concat(Math.random() < .5 ? [X.pick(STK)] : []) });\n    await S.set('d', D);\n    X.notify(c, `📓 ${X.name(c)} 在交换日记本上写了新的一页`, '', 'gyxJournalOpen');\n    X.say(c, '📓 交换日记我写好了，轮到你了。');\n    if (document.getElementById('gyxJnOv') && CID === cid) { PG = book(cid).pages.length - 1; paint(); }\n}\nwindow.gyxJournalTaNow = cid => taTurn(String(cid || CID));\nasync function tick() { if (!X.on('gyxJournal')) return;\n    for (const cid of Object.keys(D.books)) { const b = D.books[cid]; if (b.pending && Date.now() >= b.pending.at) await taTurn(cid); }\n}\nfunction pageHtml(p, i, b) {\n    const c = X.char(CID);\n    const who = p.by === 'me' ? '我' : X.name(c);\n    return `<div class=\"jn-page paper-${b.paper || 'grid'} ${p.by}\"><i class=\"jn-tape\" style=\"background:${p.tape || TAPES[i % TAPES.length]}\"></i>\n        <div class=\"jn-meta\">${new Date(p.at).toLocaleDateString()} · ${X.esc(who)}</div>\n        <div class=\"jn-text gyx-hand\">${X.esc(p.text).replace(/\\n/g, '<br>')}</div>\n        <div class=\"jn-stk\">${(p.stickers || []).map((s, k) => `<span style=\"transform:rotate(${(k * 37 % 30) - 15}deg)\">${s}</span>`).join('')}</div>\n        <div class=\"jn-no\">— ${i + 1} —</div></div>`;\n}\nfunction paint() {\n    const bd = document.getElementById('gyxJnBody'); if (!bd) return;\n    const c = X.char(CID), b = book(CID), n = b.pages.length;\n    if (EDIT) {\n        bd.innerHTML = `<div class=\"jn-page paper-${b.paper} me\"><i class=\"jn-tape\" style=\"background:${EDIT.tape}\"></i><div class=\"jn-meta\">${new Date().toLocaleDateString()} · 我</div>\n            <textarea id=\"gyxJnTx\" class=\"jn-ta gyx-hand\" placeholder=\"写点什么给 TA……\">${X.esc(EDIT.text || '')}</textarea>\n            <div class=\"jn-stk\">${EDIT.stickers.map((s, k) => `<span onclick=\"gyxJournalStk(${k},1)\">${s}</span>`).join('')}</div></div>\n            <div class=\"jn-pick\">${STK.map(s => `<span onclick=\"gyxJournalStk('${s}')\">${s}</span>`).join('')}</div>\n            <div class=\"gyx-row\">胶带：${TAPES.map(t => `<i class=\"jn-tp${EDIT.tape === t ? ' on' : ''}\" style=\"background:${t}\" onclick=\"gyxJournalTape('${t}')\"></i>`).join('')}</div>\n            <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxJournalSave()\">写好了，交给 TA</button><button class=\"gyx-btn lite\" onclick=\"gyxJournalEdit(false)\">先不写</button></div>`;\n        return;\n    }\n    if (PG < 0 || PG >= n) PG = n - 1;\n    const mine = n === 0 || b.pages[n - 1].by === 'ta';\n    bd.innerHTML = `<div class=\"gyx-row\">${X.whoSel(CID, 'gyxJournalWho')}<span class=\"gyx-tip\">纸：</span>${PAPERS.map(([t, k]) => `<span class=\"gyx-chip ${b.paper === k ? 'on' : ''}\" onclick=\"gyxJournalPaper('${k}')\">${t}</span>`).join('')}</div>\n        ${n ? pageHtml(b.pages[PG], PG, b) : `<div class=\"jn-page paper-${b.paper} cover\"><div class=\"jn-cv gyx-hand\">我和${X.esc(X.name(c))}的<br>交换日记</div></div>`}\n        <div class=\"gyx-row\" style=\"justify-content:space-between\"><button class=\"gyx-btn lite\" ${PG <= 0 ? 'disabled' : ''} onclick=\"gyxJournalGo(-1)\">‹ 上一页</button><span class=\"gyx-tip\">${n ? PG + 1 + ' / ' + n : '还是空的'}</span><button class=\"gyx-btn lite\" ${PG >= n - 1 ? 'disabled' : ''} onclick=\"gyxJournalGo(1)\">下一页 ›</button></div>\n        <div class=\"gyx-row\">${mine ? '<button class=\"gyx-btn\" onclick=\"gyxJournalEdit(true)\">✏️ 轮到我写</button>' : (b.pending ? `<span class=\"gyx-tip\">本子在 ${X.esc(X.name(c))} 那儿，TA 大概 ${Math.max(1, Math.round((b.pending.at - Date.now()) / 3600000))} 小时内写好</span><button class=\"gyx-btn lite\" onclick=\"gyxJournalTaNow()\">催一下</button>` : '<button class=\"gyx-btn lite\" onclick=\"gyxJournalEdit(true)\">✏️ 再写一页</button>')}</div>\n        <div class=\"gyx-row gyx-tip\">TA 拿到本子后过 <input class=\"gyx-who\" type=\"number\" min=\"0\" step=\"0.5\" value=\"${D.cfg.minH}\" style=\"width:60px\" onchange=\"gyxJournalCfg('minH',+this.value)\"> ~ <input class=\"gyx-who\" type=\"number\" min=\"0\" step=\"0.5\" value=\"${D.cfg.maxH}\" style=\"width:60px\" onchange=\"gyxJournalCfg('maxH',+this.value)\"> 小时写好</div>`;\n}\nwindow.gyxJournalOpen = function (who) { CID = String(who || CID || (X.cur() || {}).id || ''); EDIT = null; PG = book(CID).pages.length - 1; X.panel('gyxJnOv', '📓 交换日记本', '<div id=\"gyxJnBody\"></div>'); paint(); };\nwindow.gyxJournalWho = v => { CID = String(v); PG = -1; EDIT = null; paint(); };\nwindow.gyxJournalGo = d => { PG += d; paint(); };\nwindow.gyxJournalPaper = k => { book(CID).paper = k; S.set('d', D); paint(); };\nwindow.gyxJournalCfg = (k, v) => { D.cfg[k] = Math.max(0, v || 0); S.set('d', D); };\nwindow.gyxJournalEdit = on => { EDIT = on ? { text: '', stickers: [], tape: X.pick(TAPES) } : null; paint(); };\nwindow.gyxJournalStk = (s, del) => { const t = document.getElementById('gyxJnTx'); if (t) EDIT.text = t.value; if (del) EDIT.stickers.splice(s, 1); else EDIT.stickers.push(s); paint(); };\nwindow.gyxJournalTape = t => { const x = document.getElementById('gyxJnTx'); if (x) EDIT.text = x.value; EDIT.tape = t; paint(); };\nwindow.gyxJournalSave = async function () {\n    const t = ((document.getElementById('gyxJnTx') || {}).value || '').trim(); if (!t) { X.toast('还没写呢'); return; }\n    const b = book(CID); b.pages.push({ by: 'me', text: t, at: Date.now(), tape: EDIT.tape, stickers: EDIT.stickers });\n    const h = X.rnd(Math.min(D.cfg.minH, D.cfg.maxH), Math.max(D.cfg.minH, D.cfg.maxH)); b.pending = { at: Date.now() + h * 3600000 };\n    EDIT = null; PG = b.pages.length - 1; await S.set('d', D); paint();\n    X.toast('📓 本子交给 TA 了', `大概 ${Math.max(1, Math.round(h))} 小时内写好`);\n};\nX.ctx(id => { const b = D.books[String(id)]; if (!b || !b.pages.length) return ''; const p = b.pages[b.pages.length - 1]; return `【交换日记本】你们有一本轮流写的交换日记。最新一页是${p.by === 'me' ? '她' : '你'}写的：「${p.text.slice(0, 200)}」${b.pending ? '（本子现在在你这儿，你还没写）' : ''}`; }, 'gyxJournal');\nX.action({ key: 'gyx_journal', label: '在交换日记本上写一页', hint: '本子在你这儿，或者你想先写', need: c => { const b = D.books[String(c.id)]; return !b || !b.pages.length || b.pages[b.pages.length - 1].by === 'me'; }, run: async c => { await taTurn(String(c.id)); return '在交换日记本上写了一页'; } }, 'gyxJournal');\nX.css('gyxJnCss', `\n#gyxJnOv .gyx-box{background:#f6f1e7}#gyxJnOv .gyx-hd{background:rgba(246,241,231,.92)}\n.jn-page{position:relative;min-height:340px;margin:10px 4px;padding:28px 24px 30px;border-