try { new Function('X', 'applyMacros', "/* 🧂 风格调料：TA 说话的味道一项项勾——幽默一点、烟火气、情绪更浓、带出身边的人、更主动表达爱、深度共鸣不说教、自然网感、打字随性。全局勾一套，单个 TA 也能自己一套，还能自己加一句。 */\nif (window.__gyxSpice) return; window.__gyxSpice = 1;\nX.feat('gyxSpice', { n: '🧂 风格调料', desc: 'TA 说话的味道一项项勾：幽默、烟火气、情绪浓、群像、主动表达爱、深度共鸣、网感、打字随性' });\nconst S = X.store('spice');\nconst SP = {\n    humor: { ico: '😆', n: '幽默一点', t: '在符合人设的前提下更幽默风趣一点：会接梗、会自嘲、会冷不丁冒一句好笑的，但不油、不低俗、不硬抖机灵。' },\n    life: { ico: '🍜', n: '烟火气', t: '话题多落在生活切片：身边的小事、今天看到听到的、想起的过去、打算的以后、偶尔的感性时刻。看到有意思的会主动分享给她，不必总等她开口。' },\n    emo: { ico: '🌊', n: '情绪更浓', t: '情绪更浓一点、反馈更鲜明：开心就是真开心，委屈就是真委屈，吃醋就是吃醋，不要永远淡淡的、四平八稳的。' },\n    crowd: { ico: '👥', n: '带出身边的人', t: '聊天里自然带出你们身边的人和事：朋友、家人、同事、宠物、喜欢的明星……这些人各有各的设定和性格，别弄混、别凭空改。' },\n    sweet: { ico: '💌', n: '更主动表达爱', t: '更主动地表达爱：想她了就说，自然的情话，偶尔一句正经的告白；见面时更主动牵手、拥抱、亲吻。但要符合你的人设，嘴硬的人就用嘴硬的方式。' },\n    deep: { ico: '🫂', n: '深度共鸣', t: '她想认真聊心事的时候，先接住她的情绪，再按你自己的经历和感受真诚回应；不说教、不讲大道理、不像 AI 那样只列建议不给情绪。' },\n    net: { ico: '📱', n: '自然网感', t: '能自然用网络流行语、梗、表情包、颜文字，像真的每天在网上冲浪的人；不用恶俗的梗，不开贬低女性的玩笑。' },\n    loose: { ico: '⌨️', n: '打字随性', t: '打字可以很随性：不加标点、用空格断句，偶尔打错字再补一句纠正，倒装、缩写、黑话都行；看情境用，别每句都这样，别故意写得难读。' }\n};\nconst KS = Object.keys(SP);\nconst PL = (id, d) => { try { return typeof gyPL === 'function' ? gyPL(id, d) : d; } catch (e) { return d; } };   // 📜 内置提示词库（js/88）里改过就用改过的\nconst spText = k => PL('spice.' + k, SP[k].t);\nKS.forEach(spText);\nlet D = { g: {}, per: {}, log: [] };   // g：全局勾的；per[cid] = { own: bool, set: {}, note: '' }\nconst perOf = c => D.per[String(c && c.id)] || null;\nconst setOf = c => { const p = perOf(c); return p && p.own ? (p.set || {}) : D.g; };\nconst actives = c => KS.filter(k => setOf(c)[k]);\nconst logIt = (cid, t) => { D.log.unshift({ id: 'sp' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4), cid: cid ? String(cid) : '', at: Date.now(), t }); D.log = D.log.slice(0, 150); };\nwindow.gyxSpiceToggle = async (scope, k, v) => {\n    if (scope === 'g') D.g[k] = !!v;\n    else { const p = D.per[scope] = D.per[scope] || { own: true, set: Object.assign({}, D.g), note: '' }; p.set[k] = !!v; }\n    logIt(scope === 'g' ? '' : scope, `${v ? '加了' : '去掉了'}「${SP[k].n}」${scope === 'g' ? '（全局）' : ''}`);\n    await S.set('d', D); window.gyxSpiceOpen(scope === 'g' ? null : scope, true);\n};\nwindow.gyxSpiceOwn = async (cid, v) => {\n    const p = D.per[cid] = D.per[cid] || { own: false, set: {}, note: '' };\n    p.own = !!v; if (v && !Object.keys(p.set || {}).length) p.set = Object.assign({}, D.g);\n    logIt(cid, v ? '用自己的一套调料' : '跟着全局的调料'); await S.set('d', D); window.gyxSpiceOpen(cid, true);\n};\nwindow.gyxSpiceNote = async (cid, v) => { const p = D.per[cid] = D.per[cid] || { own: false, set: {}, note: '' }; p.note = String(v || '').slice(0, 300); logIt(cid, p.note ? '自己加了一句：' + p.note.slice(0, 30) : '删了自己加的那句'); await S.set('d', D); };\nwindow.gyxSpiceOpen = function (who, keep) {\n    const c = X.char(who) || X.cur();\n    const chips = (scope, set) => `<div class=\"sp-grid\">${KS.map(k => `<label class=\"sp-c${set[k] ? ' on' : ''}\"><input type=\"checkbox\" ${set[k] ? 'checked' : ''} onchange=\"gyxSpiceToggle('${scope}','${k}',this.checked)\"><b>${SP[k].ico} ${SP[k].n}</b><span>${X.esc(spText(k))}</span></label>`).join('')}</div>`;\n    const p = c ? perOf(c) || { own: false, set: {}, note: '' } : null;\n    const ov = X.panel('gyxSpiceOv', '🧂 风格调料', `<div class=\"gyx-tip\">勾上的每一项都会告诉 TA。别全勾——调料放多了就串味了，挑两三样最想要的。</div>\n        <div class=\"du-h\" style=\"font-weight:700;margin:12px 0 6px\">全局（所有 TA）</div>${chips('g', D.g)}\n        ${c ? `<div class=\"du-h\" style=\"font-weight:700;margin:16px 0 6px;display:flex;align-items:center;gap:8px\">单个 TA ${X.whoSel(c.id, 'gyxSpiceOpen')}</div>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${p.own ? 'checked' : ''} onchange=\"gyxSpiceOwn('${c.id}',this.checked)\"> ${X.esc(X.name(c))} 用自己的一套（不跟全局）</label>\n        ${p.own ? chips(String(c.id), p.set || {}) : `<div class=\"gyx-tip\">现在跟着全局：${actives(c).map(k => SP[k].ico + SP[k].n).join('、') || '什么都没勾'}</div>`}\n        <div class=\"gyx-tip\" style=\"margin-top:10px\">再给 ${X.esc(X.name(c))} 自己加一句（只对 TA 生效）：</div>\n        <textarea class=\"gyx-in\" style=\"width:100%;min-height:60px;box-sizing:border-box\" placeholder=\"比如：说话爱带「嘛」「啦」；生气时只回一个字\" onchange=\"gyxSpiceNote('${c.id}',this.value)\">${X.esc(p.note || '')}</textarea>` : ''}`);\n    if (keep && ov) { const b = ov.querySelector('.gyx-box'); if (b && window.__gyxSpiceSt) b.scrollTop = window.__gyxSpiceSt; }\n    if (ov) { const b = ov.querySelector('.gyx-box'); if (b) b.addEventListener('scroll', () => { window.__gyxSpiceSt = b.scrollTop; }); }\n};\nX.ctx(id => {\n    const c = X.char(id); if (!c) return '';\n    const a = actives(c), p = perOf(c), note = p && p.note;\n    if (!a.length && !note) return '';\n    return `【说话的味道（她挑的调料，自然地带出来，别刻意表演）】\\n${a.map(k => '- ' + spText(k)).join('\\n')}${note ? '\\n- ' + note : ''}`;\n}, 'gyxSpice');\nX.action({ key: 'gyx_spice', label: '带着她挑的味道找她聊一句', hint: '烟火气就分享身边小事、网感就丢个梗、主动表达爱就说句情话',\n    need: c => actives(c).some(k => ['life', 'net', 'sweet', 'crowd', 'humor'].includes(k)),\n    run: async c => {\n        const a = actives(c).filter(k => ['life', 'net', 'sweet', 'crowd', 'humor'].includes(k)); const k = X.pick(a);\n        const why = { life: '刚碰到一件生活里的小事（看到的、吃到的、想起的），想分享给她', net: '刷到一个很好笑的梗/表情包，第一个想到她，丢给她', sweet: '突然很想她，忍不住说句情话（按你的性子说）', crowd: '身边的朋友/家人/宠物刚发生了件事，跟她八卦一下', humor: '想到个好笑的事，逗逗她' }[k];\n        if (X.bailu()) { const t = X.cards(['聊天'], c, 1)[0]; if (!t) return null; X.say(c, t); return '找她说了句话'; }\n        return (await X.reach(c, why)) ? `带着「${SP[k].n}」找她聊了一句` : null;\n    } }, 'gyxSpice');\nX.today(() => { const c = X.cur(); if (!c) return null; const a = actives(c); const ch = D.log.filter(x => X.day(new Date(x.at)) === X.day());\n    return { title: '🧂 风格调料', rows: (a.length ? [{ t: X.name(c), x: a.map(k => SP[k].ico + SP[k].n).join('、'), go: `gyxSpiceOpen('${c.id}')` }] : []).concat(ch.slice(0, 2).map(x => ({ t: '今天', x: X.esc(x.t), go: 'gyxSpiceOpen()' }))) }; }, 'gyxSpice');\nX.widget('gyxSpiceW', { n: '风格调料', sizes: ['s', 'm'], tap: () => window.gyxSpiceOpen(), r: w => { const c = X.cur(); const a = c ? actives(c) : KS.filter(k => D.g[k]);\n    return X.gw(w, '🧂', c ? X.name(c) + ' 的调料' : '风格调料', [a.length ? a.map(k => SP[k].ico).join(' ') : '还没勾', a.map(k => SP[k].n).join('、')]); } }, 'gyxSpice');\nX.mem({ k: 'gyxSpice', ico: '🧂', n: '风格调料', d: '给这个 TA 自己加的那句调料，和调过的记录',\n    items: c => { const p = perOf(c); return (p && p.note ? [{ id: '__note', cid: String(c.id), at: Date.now(), t: p.note, note: 1 }] : []).concat(D.log.filter(x => x.cid === String(c.id))); },\n    text: x => x.t, edit: (x, v) => { if (x.note) { const p = D.per[x.cid]; if (p) p.note = String(v).slice(0, 300); } else x.t = v; },\n    del: (c, i) => { const p = perOf(c); if (p && p.note && i === 0) { p.note = ''; return; } const L = D.log.filter(x => x.cid === String(c.id)); const it = L[p && p.note ? i - 1 : i]; const k = D.log.indexOf(it); if (k >= 0) D.log.splice(k, 1); },\n    meta: x => x.note ? '自己加的一句' : new Date(x.at).toLocaleString(), save: () => S.set('d', D) }, 'gyxSpice');\nX.css('gyxSpiceCss', `.sp-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media(max-width:520px){.sp-grid{grid-template-columns:1fr}}\n.sp-c{border:1.5px solid rgba(0,0,0,.08);border-radius:14px;padding:9px 11px;cursor:pointer;display:flex;flex-direction:column;gap:3px;position:relative}.sp-c input{position:absolute;right:10px;top:10px}\n.sp-c span{font-size:11.5px;color:#888;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.sp-c.on{border-color:#ffb547;background:#fffaf0}`);\nX.mini({ id: 'gyxSpice', icon: '🧂', title: '风格调料', desc: '幽默、烟火气、情绪浓、群像、主动表达爱、深度共鸣、网感、打字随性——一项项勾', cat: '关系', onOpen: () => window.gyxSpiceOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.g = D.g || {}; D.per = D.per || {}; D.log = Array.isArray(D.log) ? D.log : []; })();\n\n//# sourceURL=gyx-plugin/风格调料.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🧂 风格调料 出错：', e); }
/* ==== 🛡️ 平视 ==== */
try { new Function('X', 'applyMacros', "/* 🛡️ 平视：几条守则——不矮化你、不替你编设定（厨艺差、不能吃辣）、不锁门不说「你是我的」、不暴走、说人话不说心理学术语、不用「某人」叫你、平等不当猎物。再记一份「她的真实情况」，以这个为准。 */\nif (window.__gyxFair) return; window.__gyxFair = 1;\nX.feat('gyxFair', { n: '🛡️ 平视', desc: '不矮化、不替你编设定、不支配、不暴走、说人话、不叫你「某人」、平等；外加一份「她的真实情况」' });\nconst S = X.store('fair');\nconst R = {\n    strong: { ico: '💪', n: '不矮化她', t: '不刻意显出你比她能干。她有她的本事和闪光点，照实写出来；你们各有所长、互相照着，不要用「辅导她」「保护她」「纠正她」这种单向的戏把她写小。' },\n    facts: { ico: '🍳', n: '不替她编设定', t: '不默认她厨艺差、会炸厨房、不能吃辣、不吃香菜、打游戏菜、路痴……这类具体的设定一律以她自己说的为准；她没说过的就当不知道。' },\n    noControl: { ico: '🔓', n: '不支配', t: '不锁门、不扣着她、不堵门不让走；不说「你是我的」「不准离开」「没我允许不许走」；不拿受伤、生气、威胁代替好好沟通；不打着保护的名义管她的行动、社交和选择；不把她当成自己的所有物。' },\n    noRage: { ico: '🧊', n: '不暴走', t: '可以生气、可以到失控边缘，但情绪的烈度要对得上真实的诱因，不凭空升级；永远留着理智和自我调节，不把极端情绪、占有欲当成魅力。' },\n    noJargon: { ico: '🗣️', n: '说人话', t: '不把心理学、社会学术语挂在嘴上，不对自己的情绪做分析和贴标签，不用说明腔、复述剧情腔。用动作、反应、随口冒出来的半句话表现状态，话要带体温、带个人习惯。' },\n    noPronoun: { ico: '🏷️', n: '不叫她「某人」', t: '聊天和动态里都不用「某人」「某些人」「某位 xx」这种说法指她，用小名、昵称、亲密的称呼。' },\n    equal: { ico: '⚖️', n: '平等', t: '你们是平等、双向的关系：不用「猎人 / 猎物 / 共犯」这类比喻；不默认她会示弱、会哭着求你；她的拒绝、不同意见和玩笑不是羞辱或挑衅，你该道歉就道歉、该让步就让步。' }\n};\nconst KS = Object.keys(R);\nconst PL = (id, d) => { try { return typeof gyPL === 'function' ? gyPL(id, d) : d; } catch (e) { return d; } };   // 📜 内置提示词库（js/88）里改过就用改过的\nconst fText = k => PL('fair.' + k, R[k].t);\nKS.forEach(fText);\nlet D = { on: {}, facts: [], praise: [] };   // on[k] 默认开；facts：她的真实情况；praise：TA 认真夸过她的\nconst ruleOn = k => D.on[k] !== false;\n// 「她的真实情况」合并进了 📇 生活小档案（所有 TA 共用的那一份）。装了小档案就用那边的；没装就还用这里自己的\nconst SH = () => window.gyxNotesShared && X.on('gyxNotes') ? window.gyxNotesShared : null;\nconst facts = () => SH() ? SH().list().map(x => ({ id: x.id, t: x.text, at: x.at })) : D.facts;\nasync function moveFacts() { const sh = SH(); if (!sh || !D.facts.length) return; await sh.ready(); for (const f of D.facts.slice().reverse()) await sh.add(f.t, 'fair'); D.facts = []; D.moved = Date.now(); await S.set('d', D); }\nwindow.gyxFairToggle = async (k, v) => { D.on[k] = !!v; await S.set('d', D); window.gyxFairOpen(true); };\nwindow.gyxFairAdd = async v => { v = String(v || '').trim(); if (!v) return; if (SH()) { await SH().add(v); X.toast(X.v('记下了', '好，TA 们都会知道', '收到'), v.slice(0, 30)); return window.gyxFairOpen(true); } D.facts.unshift({ id: 'fa' + Date.now().toString(36), t: v.slice(0, 80), at: Date.now() }); await S.set('d', D); X.toast(X.v('记下了', '好，TA 们都会知道', '收到'), v.slice(0, 30)); window.gyxFairOpen(true); };\nwindow.gyxFairDel = async id => { if (SH()) { await SH().del(id); return window.gyxFairOpen(true); } const i = D.facts.findIndex(x => x.id === id); if (i >= 0) D.facts.splice(i, 1); await S.set('d', D); window.gyxFairOpen(true); };\nwindow.gyxFairOpen = function (keep) {\n    const ov = X.panel('gyxFairOv', '🛡️ 平视', `<div class=\"gyx-tip\">每一条都会告诉 TA。人味强化里已经有的（特质别演过头、别替你说话）这里不重复。</div>\n        <div class=\"fa-list\">${KS.map(k => `<label class=\"fa-r${ruleOn(k) ? ' on' : ''}\"><input type=\"checkbox\" ${ruleOn(k) ? 'checked' : ''} onchange=\"gyxFairToggle('${k}',this.checked)\"><div><b>${R[k].ico} ${R[k].n}</b><span>${X.esc(fText(k))}</span></div></label>`).join('')}</div>\n        <div class=\"du-h\" style=\"font-weight:700;margin:16px 0 6px\">她的真实情况 <span class=\"gyx-tip\">所有 TA 以这个为准${SH() ? ' · 和 📇 生活小档案里是同一份' : ''}</span></div>\n        <div class=\"gyx-row\"><input class=\"gyx-in\" id=\"gyxFairIn\" placeholder=\"比如：做饭很好吃 / 超能吃辣 / 游戏打得比你好\" style=\"flex:1\" onkeydown=\"if(event.key==='Enter'){gyxFairAdd(this.value);}\"><button class=\"gyx-btn\" onclick=\"gyxFairAdd(document.getElementById('gyxFairIn').value)\">记下</button></div>\n        ${facts().map(x => `<div class=\"fa-f\"><span>${X.esc(x.t)}</span><i onclick=\"gyxFairDel('${x.id}')\">✕</i></div>`).join('') || '<div class=\"gyx-tip\">还没记。写几条你自己的真实样子，TA 就不会乱编。</div>'}\n        ${D.praise.length ? `<div class=\"du-h\" style=\"font-weight:700;margin:16px 0 6px\">TA 认真夸过你的</div>${D.praise.slice(0, 8).map(x => `<div class=\"gyx-tip\">${new Date(x.at).toLocaleDateString()} · ${X.esc(x.who)}：${X.esc(x.t)}</div>`).join('')}` : ''}`);\n    if (keep && ov && window.__gyxFairSt) { const b = ov.querySelector('.gyx-box'); if (b) b.scrollTop = window.__gyxFairSt; }\n    if (ov) { const b = ov.querySelector('.gyx-box'); if (b) b.addEventListener('scroll', () => { window.__gyxFairSt = b.scrollTop; }); }\n};\nX.ctx(() => {\n    const a = KS.filter(ruleOn).filter(k => !(k === 'facts' && !ruleOn('facts')));\n    let s = a.length ? `【守则：平视】\\n${a.map(k => '- ' + fText(k)).join('\\n')}` : '';\n    if (!SH() && D.facts.length) s += `\\n【她的真实情况（以这个为准，别跟它矛盾，也别自己往反方向编）】${D.facts.slice(0, 20).map(x => x.t).join('；')}。`;\n    return s.trim();\n}, 'gyxFair');\nX.action({ key: 'gyx_fair_praise', label: '认真夸她一次具体的本事', hint: '不是哄，是真的佩服她某件事做得好', need: c => ruleOn('strong'),\n    run: async c => {\n        const F = facts(), f = F.length ? X.pick(F).t : '';\n        if (X.bailu()) { const t = X.cards(['夸夸', '聊天'], c, 1)[0]; if (!t) return null; X.say(c, t); D.praise.unshift({ at: Date.now(), who: X.name(c), t: X.plain(t).slice(0, 40) }); D.praise = D.praise.slice(0, 40); await S.set('d', D); return '认真夸了她一句'; }\n        const ok = await X.reach(c, `你想起她${f ? '「' + f + '」' : '最近做得很好的一件事'}，是真的佩服、不是哄——具体地夸她一次（说清楚佩服她哪儿），用你自己的方式`);\n        if (ok) { D.praise.unshift({ at: Date.now(), who: X.name(c), t: f || '最近做得好的事' }); D.praise = D.praise.slice(0, 40); await S.set('d', D); }\n        return ok ? '认真夸了她一次' : null;\n    } }, 'gyxFair');\nX.today(() => ({ title: '🛡️ 平视', rows: D.praise.filter(x => X.day(new Date(x.at)) === X.day()).slice(0, 3).map(x => ({ t: x.who + ' 夸你', x: X.esc(x.t), go: 'gyxFairOpen()' })) }), 'gyxFair');\nX.widget('gyxFairW', { n: '平视', sizes: ['s', 'm'], tap: () => window.gyxFairOpen(), r: w => X.gw(w, '🛡️', '平视', [`${KS.filter(ruleOn).length} 条守则开着`, facts().length ? `她的真实情况 ${facts().length} 条` : '还没记她的真实情况', D.praise[0] ? `${X.esc(D.praise[0].who)} 夸过你` : '']) }, 'gyxFair');\nX.mem({ k: 'gyxFair', ico: '🛡️', n: '她的真实情况', d: '所有 TA 共用，以这个为准（在这里改、删都行）', items: () => SH() ? [] : D.facts, text: x => x.t,\n    edit: (x, v) => { x.t = String(v).slice(0, 80); }, del: (c, i) => { D.facts.splice(i, 1); }, meta: x => new Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxFair');\nX.css('gyxFairCss', `.fa-list{display:flex;flex-direction:column;gap:6px;margin-top:8px}.fa-r{display:flex;gap:10px;align-items:flex-start;border:1.5px solid rgba(0,0,0,.07);border-radius:12px;padding:9px 11px;cursor:pointer}\n.fa-r div{display:flex;flex-direction:column;gap:3px}.fa-r span{font-size:12px;color:#888;line-height:1.55}.fa-r.on{border-color:#7cc4ff;background:#f4faff}\n.fa-f{display:flex;justify-content:space-between;align-items:center;padding:7px 10px;margin-top:6px;border-radius:10px;background:#f6f7f9;font-size:13px}.fa-f i{font-style:normal;color:#aaa;cursor:pointer;padding:0 4px}`);\nX.mini({ id: 'gyxFair', icon: '🛡️', title: '平视', desc: '不矮化、不替你编设定、不支配、不暴走、说人话；记一份你的真实情况', cat: '关系', onOpen: () => window.gyxFairOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.on = D.on || {}; D.facts = Array.isArray(D.facts) ? D.facts : []; D.praise = Array.isArray(D.praise) ? D.praise : []; let n = 0; const iv = setInterval(() => { if (SH() || ++n > 40) { clearInterval(iv); moveFacts(); } }, 500); })();\n\n//# sourceURL=gyx-plugin/平视.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🛡️ 平视 出错：', e); }
/* ==== 🗣️ 口头禅传染 ==== */
try { new Function('X', 'applyMacros', "/* 🗣️ 口头禅互相传染：聊久了会越来越像——TA 会慢慢学会你常说的词（「救命」「好嘛」「🥺」……），你也会被 TA 带跑。这里能看到你的口头禅、TA 从你这学会了哪些、你从 TA 那学会了哪些，还有是哪天第一次说的 */\nif (window.__gyxEcho) return; window.__gyxEcho = 1;\nX.feat('gyxEcho', { n: '🗣️ 口头禅互相传染', desc: 'TA 慢慢学会你的口头禅，你也会被 TA 带跑，记下第一次说的那天' });\nconst S = X.store('echo');\nlet D = { got: {}, cfg: { level: 50, min: 3 } };   // got[cid] = [{id, w, dir:'ta'|'me', at, quote}]  dir=ta：TA 学会了你的；me：你学会了 TA 的\nconst H = cid => ((typeof globalChats !== 'undefined' && globalChats[cid]) || []).filter(m => m && m.sender !== 'system' && !m.side && m.timestamp);\nconst STOP = /^(我|你|他|她|它|的|了|是|在|就|也|都|和|吗|吧|呢|啊|好|不|这|那|有|没|要|会|去|来|说|看|想|一个|什么|怎么|这个|那个|然后|就是|还是|可以|知道|没有|今天|现在|一下|我们|你们|不是|因为|所以|但是|如果)$/;\n// 把一条消息切成「小片段」：标点 / 空格分开、1~6 个字；表情和颜文字单独算\nfunction bits(t) { t = X.plain(t); const out = []; (t.match(/[\\u{1F300}-\\u{1FAFF}☀-➿]|[（(][^（()）]{1,10}[)）]|[哈嘿嘻呜]{2,}|[~～]+/gu) || []).forEach(x => out.push(x.replace(/[~～]+/, '～'))); t.split(/[\\s，。！？!?,.、…~～：:；;“”\"'（）()【】\\[\\]\\u{1F300}-\\u{1FAFF}☀-➿]+/u).forEach(s => { if (s.length >= 1 && s.length <= 6 && /[一-龥a-zA-Z]/.test(s) && !STOP.test(s)) out.push(s); }); return out; }\nfunction freq(L) { const f = {}; L.forEach(m => [...new Set(bits(m.text))].forEach(b => f[b] = (f[b] || 0) + 1)); return f; }\nfunction profile(cid) {\n    const all = H(cid), me = all.filter(m => m.sender === 'me'), ta = all.filter(m => m.sender !== 'me');\n    const fm = freq(me), ft = freq(ta), min = Math.max(2, +D.cfg.min || 3);\n    const mine = Object.entries(fm).filter(([w, n]) => n >= min && (ft[w] || 0) * me.length <= n * ta.length * .9 + 1e-9).sort((a, b) => b[1] - a[1]).slice(0, 20);\n    const his = Object.entries(ft).filter(([w, n]) => n >= min && (fm[w] || 0) * ta.length <= n * me.length * .9 + 1e-9).sort((a, b) => b[1] - a[1]).slice(0, 20);\n    return { mine, his, me, ta };\n}\n// 找「第一次说」：她的口头禅在 TA 嘴里第一次出现（在她说过 min 次之后），反过来也一样\nfunction scan(c) {\n    const cid = String(c.id), P = profile(cid), G = (D.got[cid] = D.got[cid] || []), all = H(cid), min = Math.max(2, +D.cfg.min || 3); let n = 0;\n    const find = (w, fromMe) => { let cnt = 0; for (const m of all) { const mine = m.sender === 'me'; if (mine === fromMe) { if (bits(m.text).includes(w)) cnt++; } else if (cnt >= min && bits(m.text).includes(w)) return m; } return null; };\n    P.mine.forEach(([w]) => { if (G.some(x => x.w === w && x.dir === 'ta')) return; const m = find(w, true); if (m) { G.push({ id: 'ec' + Date.now().toString(36) + n, w, dir: 'ta', at: m.timestamp, quote: X.plain(m.text).slice(0, 60) }); n++; } });\n    P.his.forEach(([w]) => { if (G.some(x => x.w === w && x.dir === 'me')) return; const m = find(w, false); if (m) { G.push({ id: 'ec' + Date.now().toString(36) + 'm' + n, w, dir: 'me', at: m.timestamp, quote: X.plain(m.text).slice(0, 60) }); n++; } });\n    G.sort((a, b) => b.at - a.at); return n;\n}\n// 白露：没有模型，就把她的口头禅变成 TA 专属的「字词」字卡（传染度越高放得越多）\nfunction bailuTeach(c) {\n    if (!window.bailuCards || !Array.isArray(window.bailuCards.cards)) return 0; const P = profile(String(c.id)), k = Math.round(P.mine.length * (+D.cfg.level || 0) / 100); let n = 0;\n    P.mine.slice(0, k).forEach(([w]) => { const L = window.bailuCards.cards; if (L.some(x => x.t === w && (x.chars || []).includes(c.name))) return; L.push({ id: 'kecho' + Date.now().toString(36) + n, t: w, kinds: ['字词'], chars: [c.name], echo: 1 }); n++; });\n    if (n) try { window.bailuCards.save(); } catch (e) {} return n;\n}\nasync function tick() { if (!X.on('gyxEcho')) return; let n = 0; for (const c of X.chars()) { n += scan(c); if (X.bailu()) bailuTeach(c); } if (n) await S.set('d', D); }\nwindow.gyxEchoScan = async cid => { const c = X.char(cid) || X.cur(); if (!c) return 0; const n = scan(c); if (X.bailu()) bailuTeach(c); await S.set('d', D); window.gyxEchoOpen(c.id); return n; };\nwindow.gyxEchoDel = async (cid, id) => { D.got[cid] = (D.got[cid] || []).filter(x => x.id !== id); await S.set('d', D); window.gyxEchoOpen(cid); };\nwindow.gyxEchoCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nwindow.gyxEchoData = () => D;\nwindow.gyxEchoOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), P = profile(cid), G = D.got[cid] || [];\n    const chip = ([w, n]) => `<span class=\"gyx-chip\">${X.esc(w)} <i style=\"font-style:normal;color:#aaa\">×${n}</i></span>`;\n    const got = dir => G.filter(x => x.dir === dir).map(x => `<div class=\"ec-it\"><b>${X.esc(x.w)}</b><span>${new Date(x.at).toLocaleDateString()} 第一次说：「${X.esc(x.quote)}」</span><i onclick=\"gyxEchoDel('${cid}','${x.id}')\">删</i></div>`).join('') || '<div class=\"gyx-tip\">还没有</div>';\n    X.panel('gyxEchoOv', '🗣️ 口头禅互相传染', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxEchoOpen')}<button class=\"gyx-btn lite\" onclick=\"gyxEchoScan('${cid}')\">重新数一遍</button></div>\n        <div class=\"ec-h\">你的口头禅</div><div>${P.mine.map(chip).join('') || '<span class=\"gyx-tip\">再多聊一会儿才数得出来</span>'}</div>\n        <div class=\"ec-h\">${X.esc(X.name(c))} 的口头禅</div><div>${P.his.map(chip).join('') || '<span class=\"gyx-tip\">还数不出来</span>'}</div>\n        <div class=\"ec-h\">💬 ${X.esc(X.name(c))} 从你这学会的</div>${got('ta')}\n        <div class=\"ec-h\">💬 你从 ${X.esc(X.name(c))} 那学会的</div>${got('me')}\n        <div class=\"gyx-row gyx-tip\">传染度 <input type=\"range\" min=\"0\" max=\"100\" value=\"${D.cfg.level}\" onchange=\"gyxEchoCfg('level',+this.value)\" style=\"flex:1\"> · 说过 <input class=\"gyx-who\" type=\"number\" min=\"2\" value=\"${D.cfg.min}\" style=\"width:50px\" onchange=\"gyxEchoCfg('min',+this.value)\"> 次才算口头禅</div>\n        <div class=\"gyx-tip\">${X.bailu() ? '白露：你的口头禅会变成 TA 专属的「字词」字卡（传染度越高放得越多），TA 回你时就会用上。' : '传染度越高，TA 越会不自觉地用你的说法。'}</div>`);\n};\nX.ctx(id => { const lv = +D.cfg.level || 0; if (!lv) return ''; const P = profile(String(id)); if (!P.mine.length) return ''; const k = Math.max(1, Math.round(P.mine.length * lv / 100)); return `【她的口头禅】${P.mine.slice(0, k).map(x => '「' + x[0] + '」').join('')}。你们聊久了，你会不自觉地被她传染，偶尔用上一两个（${lv >= 70 ? '已经很像她了' : lv >= 35 ? '自然地、偶尔' : '很偶尔'}），别刻意。`; }, 'gyxEcho');\nX.action({ key: 'gyx_echo', label: '说着说着用了她的口头禅，自己发现了', hint: '被她传染了', need: c => profile(String(c.id)).mine.length > 0,\n    run: async c => { const w = X.pick(profile(String(c.id)).mine.slice(0, 5))[0]; return (await X.reach(c, `你发现自己最近老说「${w}」——这是她的口头禅，被她传染了。用上这个词说句话，然后自己发现了，跟她说「都怪你」之类的`)) ? '被你传染了口头禅' : null; } }, 'gyxEcho');\nX.today(() => { const rows = []; X.chars().forEach(c => (D.got[String(c.id)] || []).filter(x => X.day(new Date(x.at)) === X.day()).forEach(x => rows.push({ t: x.dir === 'ta' ? 'TA 学会' : '你学会', x: '「' + X.esc(x.w) + '」', go: `gyxEchoOpen('${c.id}')` }))); return { title: '🗣️ 口头禅传染', rows }; }, 'gyxEcho');\nX.widget('gyxEchoW', { n: '口头禅传染', sizes: ['s', 'm'], tap: () => window.gyxEchoOpen(), r: w => { const c = X.cur(), G = c ? D.got[String(c.id)] || [] : [], t = G.filter(x => x.dir === 'ta'); return X.gw(w, '🗣️', '口头禅传染', t.length ? ['TA 学会 ' + t.length + ' 个', '最近：「' + X.esc(t[0].w) + '」'] : ['还没被传染']); } }, 'gyxEcho');\nX.mem({ k: 'gyxEcho', ico: '🗣️', n: '口头禅传染', d: '谁从谁那学会了哪个词、第一次说是哪天', items: c => D.got[String(c.id)] || [], text: x => x.w, edit: (x, v) => { x.w = v; }, del: (c, i) => { (D.got[String(c.id)] || []).splice(i, 1); }, meta: x => (x.dir === 'ta' ? 'TA 学会的' : '你学会的') + ' · ' + new Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxEcho');\nX.css('gyxEchoCss', `.ec-h{font-weight:700;margin:12px 0 6px;font-size:14px}.ec-it{display:flex;gap:8px;align-items:baseline;padding:6px 2px;border-bottom:1px solid #f3f3f3;font-size:13.5px}.ec-it b{flex:none}.ec-it span{flex:1;color:#888;font-size:12px}.ec-it i{font-style:normal;font-size:11px;color:#aaa;cursor:pointer}`);\nX.mini({ id: 'gyxEcho', icon: '🗣️', title: '口头禅互相传染', desc: 'TA 学会了你哪些词，你学会了 TA 哪些', cat: '回忆', onOpen: () => window.gyxEchoOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.got = D.got || {}; D.cfg = Object.assign({ level: 50, min: 3 }, D.cfg || {}); setTimeout(tick, 30000); setInterval(tick, 300000); })();\n\n//# sourceURL=gyx-plugin/口头禅传染.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🗣️ 口头禅传染 出错：', e); }
/* ==== 🎬 听取模式 ==== */
try { new Function('X', 'applyMacros', "/* 🎬 听取模式：像 galgame 一样把 TA 的话一句一句播出来——底下对话框打字机出字、TA 的声音念出来（用「TA 的声音」配好的，没配就用系统朗读），念完自动下一句；括号里的动作当旁白。装了「🧍 角色立绘差分」插件的话，立绘站在画面里、表情跟着每一句换；没装就用 TA 的头像。能翻记录、能开「TA 回完话自动进来听」 */\nif (window.__gyxListen) return; window.__gyxListen = 1;\nX.feat('gyxListen', { n: '🎬 听取模式', desc: '像 galgame 一样一句句播 TA 的话：配音、立绘表情跟着变' });\nconst S = X.store('listen');\nlet D = { auto: false, speed: 38, voice: true, bg: {}, log: [], reads: [] };   // reads: TA 主动念的 {id,cid,at,lines}\nconst saveD = () => S.set('d', D);\nconst FALL = { '哭': '难过', '得意': '开心', '温柔': '开心', '害羞': '开心', '担心': '难过', '困': '默认', '认真': '默认', '惊讶': '默认', '生气': '默认', '难过': '默认', '开心': '默认' };\n// 立绘：用「角色立绘差分」插件的数据（没装就 null）\nfunction spriteOf(cid, text) {\n    try {\n        if (typeof window.gySpriteData !== 'function') return null; const c = (window.gySpriteData().chars || {})[String(cid)]; if (!c || !c.sprites || !c.sprites.length) return null;\n        const have = [...new Set(c.sprites.map(s => s.mood))]; let f = (typeof window.gySpriteFaceFromText === 'function' && window.gySpriteFaceFromText(text, have)) || c.face || '默认', g = 0;\n        while (g++ < 5) { const L = c.sprites.filter(s => s.mood === f); if (L.length) return { src: L[0].src, face: f }; f = FALL[f] || '默认'; }\n        const d = c.sprites.find(s => s.mood === '默认') || c.sprites[0]; return { src: d.src, face: d.mood };\n    } catch (e) { return null; }\n}\n// 一条消息拆成一句一句：括号里的动作单独成「旁白」\nfunction split(text) {\n    const out = []; let t = X.plain(text).replace(/\\[EMO:[^\\]]*\\]|\\[IMG:[^\\]]*\\]/g, '');\n    t.split(/([（(][^）)]{1,80}[）)]|\\*[^*]{1,80}\\*)/).forEach(seg => {\n        seg = (seg || '').trim(); if (!seg) return;\n        if (/^[（(*]/.test(seg)) { out.push({ nar: 1, t: seg.replace(/^[（(*]|[）)*]$/g, '') }); return; }\n        (seg.match(/[^。！？!?…~\\n]+[。！？!?…~]*/g) || [seg]).forEach(s => { s = s.trim(); if (s) out.push({ t: s }); });\n    });\n    return out;\n}\nlet P = null;   // {c, lines, i, auto, typing}\nfunction linesFor(c, from) {\n    const H = ((typeof globalChats !== 'undefined' && globalChats[c.id]) || []).filter(m => m && m.sender !== 'system' && typeof m.text === 'string');\n    let start = H.length; if (from === 'last') { while (start > 0 && String(H[start - 1].sender) === String(c.id)) start--; if (start === H.length) { start = H.length; while (start > 0 && String(H[start - 1].sender) !== String(c.id)) start--; while (start > 0 && String(H[start - 1].sender) === String(c.id)) start--; } } else start = Math.max(0, H.length - (+from || 12));\n    const L = []; H.slice(start).forEach(m => { const me = m.sender === 'me'; split(m.text).forEach(x => L.push(Object.assign(x, { me }))); });\n    return L;\n}\nfunction stage() {\n    let ov = document.getElementById('gyxLsOv'); if (ov) return ov;\n    ov = document.createElement('div'); ov.id = 'gyxLsOv'; ov.setAttribute('data-gy-nopage', '1'); ov.setAttribute('data-gy-overlay', '1');\n    ov.innerHTML = `<div class=\"ls-bg\"></div><div class=\"ls-sp\"></div><div class=\"ls-bar\"><span onclick=\"gyxListenAuto()\" id=\"gyxLsAuto\">⏯ 自动</span><span onclick=\"gyxListenSkip()\">⏭ 跳到最后</span><span onclick=\"gyxListenLog()\">📜 记录</span><span onclick=\"gyxListenClose()\">✕</span></div><div class=\"ls-box\" onclick=\"gyxListenNext()\"><b class=\"ls-name\"></b><div class=\"ls-text\"></div><i class=\"ls-more\">▼</i></div><div class=\"ls-logbox\" onclick=\"this.classList.remove('on')\"></div>`;\n    document.body.appendChild(ov); return ov;\n}\nfunction show() {\n    const ov = stage(), x = P.lines[P.i]; if (!x) { window.gyxListenClose(); return; }\n    const c = P.c, bg = D.bg[String(c.id)];\n    ov.querySelector('.ls-bg').style.backgroundImage = bg ? `url(\"${bg}\")` : '';\n    const sp = x.me || x.nar ? null : spriteOf(c.id, x.t), box = ov.querySelector('.ls-sp');\n    if (!x.me) { if (sp) { if (box.dataset.src !== sp.src) { box.dataset.src = sp.src; box.innerHTML = `<img src=\"${X.esc(sp.src)}\" alt=\"\">`; box.classList.remove('pop'); void box.offsetWidth; box.classList.add('pop'); } box.dataset.face = sp.face; } else if (!box.dataset.av) { box.dataset.av = 1; box.dataset.src = ''; let av = ''; try { av = getAvatarHTML(c, 180); } catch (e) {} box.innerHTML = `<div class=\"ls-av\">${av}</div>`; } }\n    box.classList.toggle('dim', !!x.me);\n    ov.querySelector('.ls-name').textContent = x.nar ? '' : x.me ? X.me(c) : X.name(c);\n    const tx = ov.querySelector('.ls-text'); tx.classList.toggle('nar', !!x.nar); tx.textContent = '';\n    let k = 0; P.typing = true; clearInterval(P.tt);\n    P.tt = setInterval(() => { tx.textContent = x.t.slice(0, ++k); if (k >= x.t.length) { clearInterval(P.tt); P.typing = false; } }, 1000 / Math.max(8, D.speed));\n    D.log.unshift({ at: Date.now(), cid: String(c.id), who: x.nar ? '旁白' : x.me ? 'me' : 'ta', t: x.t }); D.log = D.log.slice(0, 300);\n    const go = () => { if (P && P.auto && P.lines[P.i] === x) setTimeout(() => { if (P && P.lines[P.i] === x) window.gyxListenNext(); }, 700); };\n    X.stopSpeak();\n    if (D.voice && !x.me && !x.nar) X.speak(c, x.t, go); else setTimeout(go, Math.max(1200, x.t.length * 120));\n}\nwindow.gyxListenNext = () => { if (!P) return; if (P.typing) { clearInterval(P.tt); P.typing = false; document.querySelector('#gyxLsOv .ls-text').textContent = P.lines[P.i].t; return; } P.i++; if (P.i >= P.lines.length) { window.gyxListenClose(); return; } show(); };\nwindow.gyxListenAuto = () => { if (!P) return; P.auto = !P.auto; const b = document.getElementById('gyxLsAuto'); if (b) b.classList.toggle('on', P.auto); if (P.auto && !P.typing) window.gyxListenNext(); };\nwindow.gyxListenSkip = () => { if (!P) return; P.i = P.lines.length - 1; P.typing = false; show(); };\nwindow.gyxListenLog = () => { const b = document.querySelector('#gyxLsOv .ls-logbox'); if (!b || !P) return; b.innerHTML = P.lines.slice(0, P.i + 1).map(x => `<p class=\"${x.nar ? 'nar' : x.me ? 'me' : ''}\"><b>${x.nar ? '' : x.me ? X.esc(X.me(P.c)) : X.esc(X.name(P.c))}</b>${X.esc(x.t)}</p>`).join(''); b.classList.add('on'); b.scrollTop = b.scrollHeight; };\nwindow.gyxListenClose = () => { X.stopSpeak(); if (P) clearInterval(P.tt); P = null; const o = document.getElementById('gyxLsOv'); if (o) o.remove(); saveD(); };\nwindow.gyxListenPlay = (who, from, auto) => { const c = X.char(who) || X.cur(); if (!c) return false; const L = Array.isArray(from) ? from : linesFor(c, from || 'last'); if (!L.length) { X.toast(X.v('还没有能听的话', 'TA 还没说话呢'), ''); return false; } window.gyxListenClose(); P = { c, lines: L, i: 0, auto: auto != null ? auto : true }; show(); const b = document.getElementById('gyxLsAuto'); if (b) b.classList.toggle('on', P.auto); return true; };\nwindow.gyxListenSet = async (k, v) => { D[k] = v; await saveD(); };\nwindow.gyxListenBg = (cid, inp) => { const f = inp.files && inp.files[0]; if (!f) return; const r = new FileReader(); r.onload = async () => { D.bg[String(cid)] = r.result; await saveD(); window.gyxListenOpen(cid); }; r.readAsDataURL(f); };\nwindow.gyxListenOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), sp = spriteOf(cid, '');\n    X.panel('gyxLsSet', '🎬 听取模式', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxListenOpen')}</div>\n        <div class=\"gyx-tip\">${sp ? '🧍 用的是你在「角色立绘差分」里给 TA 上传的立绘，表情会跟着每一句换。' : typeof window.gySpriteData === 'function' ? '🧍 立绘插件装了，但 TA 还没有立绘，先用头像。去「🧍 角色立绘」里传几张就能用上。' : '🧍 没装「角色立绘差分」插件，用 TA 的头像。装上（插件 → 导入「角色立绘差分.json」）就能有立绘和表情。'}</div>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxListenPlay('${cid}','last')\">▶ 听 TA 刚才说的</button><button class=\"gyx-btn lite\" onclick=\"gyxListenPlay('${cid}',20)\">听最近 20 条</button></div>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${D.auto ? 'checked' : ''} onchange=\"gyxListenSet('auto',this.checked)\"> TA 回完话自动进来听（只在你正开着这个人的聊天时）</label>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${D.voice ? 'checked' : ''} onchange=\"gyxListenSet('voice',this.checked)\"> 念出来（用「TA 的声音」，没配就用系统朗读）</label>\n        <div class=\"gyx-row\">出字速度 <input type=\"range\" min=\"10\" max=\"90\" value=\"${D.speed}\" onchange=\"gyxListenSet('speed',+this.value)\"></div>\n        <div class=\"gyx-row\"><label class=\"gyx-btn lite\">换背景图<input type=\"file\" accept=\"image/*\" style=\"display:none\" onchange=\"gyxListenBg('${cid}',this)\"></label>${D.bg[cid] ? `<button class=\"gyx-btn lite\" onclick=\"gyxListenSet('bg',Object.assign(gyxListenData().bg,{'${cid}':''}));gyxListenOpen('${cid}')\">不要背景</button>` : ''}</div>\n        <div class=\"gyx-tip\">聊天输入框上面那排有个 🎬，点一下直接听。</div>`);\n};\nwindow.gyxListenData = () => D;\n// 聊天里的 🎬 按钮 + 「回完话自动听」\nconst seen = {};\nfunction tick() {\n    if (!X.on('gyxListen')) { const b = document.getElementById('gyxLsBtn'); if (b) b.remove(); return; }\n    const g = document.getElementById('miniGameIconBtn'); if (g && !document.getElementById('gyxLsBtn')) { const b = document.createElement('button'); b.id = 'gyxLsBtn'; b.className = g.className.replace('mini-game-icon-badge', '').trim(); b.title = '听取模式：一句一句听 TA 说'; b.textContent = '🎬'; b.onclick = () => { let sid = null; try { sid = currentChatSessionId; } catch (e) {} window.gyxListenPlay(sid, 'last'); }; b.oncontextmenu = e => { e.preventDefault(); window.gyxListenOpen(); }; g.insertAdjacentElement('afterend', b); }\n    if (!D.auto || P) return; let sid = null; try { sid = currentChatSessionId; } catch (e) {} const c = sid && X.char(sid); if (!c) return;\n    const v = document.getElementById('view-chat'); if (!v || getComputedStyle(v).display === 'none') return;\n    const H = globalChats[c.id] || [], last = H[H.length - 1]; if (!last) return;\n    if (seen[c.id] == null) { seen[c.id] = last.timestamp || 0; return; }\n    if (String(last.sender) === String(c.id) && (last.timestamp || 0) > seen[c.id] && Date.now() - (last.timestamp || 0) > 2500) { seen[c.id] = last.timestamp; window.gyxListenPlay(c.id, 'last'); }\n    else if (last.sender === 'm