    //    每个插件 X.recapDef 登记自己能怎么调，X.recap(key) 读你选的；在「📚 回顾 → ⚙️ 多久总结一次」里改
    const RK = 'gyxRecap'; let RC = {}; try { RC = JSON.parse(localStorage.getItem(RK) || '{}') || {}; } catch (e) {}
    X.RECAP = window.__gyxRecapDefs = window.__gyxRecapDefs || [];
